{
  "name": "QuizGenius - Self-Testing Platform",
  "description": "A professional self-testing application that supports multiple question types (objective & subjective), quiz sharing via keys, and automatic grading."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum QuestionType {
  SINGLE_CHOICE = 'SINGLE_CHOICE',
  MULTIPLE_CHOICE = 'MULTIPLE_CHOICE',
  FILL_IN_THE_BLANK = 'FILL_IN_THE_BLANK',
  TRUE_FALSE = 'TRUE_FALSE',
  SUBJECTIVE = 'SUBJECTIVE',
}

export interface Option {
  id: string;
  text: string;
}

export interface Question {
  id: string;
  type: QuestionType;
  text: string;
  options?: Option[]; // For Single/Multiple Choice
  correctAnswers: string[]; // For Single (1 item), Multiple (many), Fill (many valid), T/F ("true"/"false")
  subjectiveReference?: string; // For Subjective
  explanation?: string;
  points: number;
}

export interface QuizSet {
  id: string;
  title: string;
  description: string;
  createdAt: number;
  questions: Question[];
}

export type UserAnswers = Record<string, string | string[]>;

export interface GradeResult {
  questionId: string;
  isCorrect: boolean;
  score: number;
  maxScore: number;
  feedback?: string;
}

import { QuizSet } from '../types';

/**
 * Encodes a QuizSet into a Base64 string (Share Key)
 */
export const encodeQuizKey = (quiz: QuizSet): string => {
  try {
    const jsonStr = JSON.stringify(quiz);
    // In a real app, we might use a compression library or simple encryption
    return btoa(encodeURIComponent(jsonStr));
  } catch (e) {
    console.error("Failed to encode quiz key", e);
    return '';
  }
};

/**
 * Decodes a Share Key back into a QuizSet
 */
export const decodeQuizKey = (key: string): QuizSet | null => {
  try {
    const jsonStr = decodeURIComponent(atob(key));
    return JSON.parse(jsonStr) as QuizSet;
  } catch (e) {
    console.error("Failed to decode quiz key", e);
    return null;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'success';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({
  children,
  variant = 'primary',
  size = 'md',
  isLoading,
  className = '',
  ...props
}) => {
  const baseStyles = 'inline-flex items-center justify-center font-medium transition-all duration-200 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed';

  const variants = {
    primary: 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-sm',
    secondary: 'bg-white text-slate-700 border border-slate-200 hover:bg-slate-50',
    danger: 'bg-red-500 text-white hover:bg-red-600 shadow-sm',
    success: 'bg-emerald-500 text-white hover:bg-emerald-600 shadow-sm',
    ghost: 'bg-transparent text-slate-600 hover:bg-slate-100',
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2 text-base',
    lg: 'px-6 py-3 text-lg',
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading && (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      )}
      {children}
    </button>
  );
};

import React from 'react';
import { QuizSet } from '../types';
import { Button } from './Button';

