import React from 'react';
import { Question, QuestionType } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: string | string[];
  onChange: (value: string | string[]) => void;
  isGraded?: boolean;
}

export const QuestionRenderer: React.FC<QuestionRendererProps> = ({
  question,
  index,
  answer,
  onChange,
  isGraded = false
}) => {
  const handleSingleChoice = (optionId: string) => {
    if (isGraded) return;
    onChange(optionId);
  };

  const handleMultipleChoice = (optionId: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) ? answer : [];
    if (currentAnswers.includes(optionId)) {
      onChange(currentAnswers.filter(id => id !== optionId));
    } else {
      onChange([...currentAnswers, optionId]);
    }
  };

  const handleTrueFalse = (val: string) => {
    if (isGraded) return;
    onChange(val);
  };

  return (
    <div className={`p-6 rounded-xl bg-white border ${isGraded ? 'border-slate-200' : 'border-indigo-100 shadow-sm'}`}>
      <div className="flex items-start gap-4 mb-4">
        <span className="flex-shrink-0 w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold text-sm">
          {index + 1}
        </span>
        <div className="flex-grow">
          <div className="flex items-center gap-2 mb-1">
             <span className="text-xs font-bold uppercase tracking-wider text-slate-400">
               {question.type.replace(/_/g, ' ')}
             </span>
             <span className="text-xs text-slate-400">• {question.points} pts</span>
          </div>
          <h4 className="text-lg font-medium text-slate-800 whitespace-pre-wrap">{question.text}</h4>
        </div>
      </div>

      <div className="ml-12 space-y-3">
        {question.type === QuestionType.SINGLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              answer === opt.id 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="radio" 
              name={`q-${question.id}`} 
              checked={answer === opt.id}
              onChange={() => handleSingleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.MULTIPLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              Array.isArray(answer) && answer.includes(opt.id) 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="checkbox" 
              checked={Array.isArray(answer) && answer.includes(opt.id)}
              onChange={() => handleMultipleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.TRUE_FALSE && (
          <div className="flex gap-4">
            {['true', 'false'].map(val => (
              <button
                key={val}
                onClick={() => handleTrueFalse(val)}
                className={`flex-1 py-3 px-4 rounded-lg border font-medium capitalize transition-all ${
                  answer === val 
                    ? 'border-indigo-600 bg-indigo-600 text-white shadow-md' 
                    : 'border-slate-200 text-slate-600 hover:bg-slate-50'
                } ${isGraded ? 'pointer-events-none' : ''}`}
              >
                {val}
              </button>
            ))}
          </div>
        )}

        {question.type === QuestionType.FILL_IN_THE_BLANK && (
          <input
            type="text"
            placeholder="Type your answer here..."
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
            disabled={isGraded}
          />
        )}

        {question.type === QuestionType.SUBJECTIVE && (
          <textarea
            placeholder="Write your answer in detail..."
            rows={4}
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
            disabled={isGraded}
          />
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, Question, QuestionType, Option } from '../types';
import { Button } from './Button';

interface QuizEditorProps {
  onSave: (quiz: QuizSet) => void;
  onCancel: () => void;
  initialQuiz?: QuizSet;
}

export const QuizEditor: React.FC<QuizEditorProps> = ({ onSave, onCancel, initialQuiz }) => {
  const [title, setTitle] = useState(initialQuiz?.title || '');
  const [description, setDescription] = useState(initialQuiz?.description || '');
  const [questions, setQuestions] = useState<Question[]>(initialQuiz?.questions || []);

  const addQuestion = (type: QuestionType) => {
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      text: '',
      points: 5,
      correctAnswers: [],
      options: (type === QuestionType.SINGLE_CHOICE || type === QuestionType.MULTIPLE_CHOICE) 
        ? [{ id: '1', text: 'Option 1' }, { id: '2', text: 'Option 2' }] 
        : undefined,
    };
    setQuestions([...questions, newQuestion]);
  };

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter(q => q.id !== id));
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  const handleSave = () => {
    if (!title) {
      alert("Please provide a title");
      return;
    }
    onSave({
      id: initialQuiz?.id || Math.random().toString(36).substr(2, 9),
      title,
      description,
      createdAt: Date.now(),
      questions,
    });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-20">
      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h2 className="text-xl font-bold text-slate-800 mb-6">General Information</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Quiz Title</label>
            <input 
              type="text" 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="E.g., Mid-Term Physics Quiz"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
            <textarea 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              rows={3}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What is this quiz about?"
            />
          </div>
        </div>
      </section>

      <section className="space-y-6">
        <div className="flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800">Questions ({questions.length})</h2>
          <div className="flex flex-wrap gap-2">
            {Object.values(QuestionType).map(type => (
              <Button key={type} size="sm" variant="secondary" onClick={() => addQuestion(type)}>
                + {type.replace(/_/g, ' ').toLowerCase()}
              </Button>
            ))}
          </div>
        </div>

        {questions.length === 0 ? (
          <div className="text-center py-12 bg-slate-100 rounded-2xl border-2 border-dashed border-slate-300">
            <p className="text-slate-500">No questions added yet. Use the buttons above to start building.</p>
          </div>
        ) : (
          questions.map((q, idx) => (
            <div key={q.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 relative group">
              <button 
                onClick={() => removeQuestion(q.id)}
                className="absolute top-4 right-4 text-slate-300 hover:text-red-500 p-1 rounded-full hover:bg-red-50 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>

              <div className="mb-4">
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Question {idx + 1} - {q.type}</label>
                <textarea
                  className="w-full p-3 bg-slate-50 rounded-lg border border-slate-200 font-medium outline-none focus:bg-white focus:ring-2 focus:ring-indigo-500 transition-all"
                  rows={2}
                  value={q.text}
                  onChange={(e) => updateQuestion(q.id, { text: e.target.value })}
                  placeholder="Enter the question text..."
                />
              </div>

              {/* Specific Editor based on type */}
              <div className="mt-4 space-y-4">
                {(q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE) && (
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">Options & Correct Answers</label>
                    {q.options?.map(opt => (
                      <div key={opt.id} className="flex items-center gap-3">
                        <input 
                          type={q.type === QuestionType.SINGLE_CHOICE ? "radio" : "checkbox"} 
                          checked={q.correctAnswers.includes(opt.id)}
                          onChange={() => {
                            if (q.type === QuestionType.SINGLE_CHOICE) {
                              updateQuestion(q.id, { correctAnswers: [opt.id] });
                            } else {
                              const news = q.correctAnswers.includes(opt.id) 
                                ? q.correctAnswers.filter(id => id !== opt.id)
                                : [...q.correctAnswers, opt.id];
                              updateQuestion(q.id, { correctAnswers: news });
                            }
                          }}
                        />
                        <input 
                          type="text" 
                          className="flex-grow p-2 rounded-md border border-slate-200 text-sm"
                          value={opt.text}
                          onChange={(e) => {
                            const newOpts = q.options?.map(o => o.id === opt.id ? { ...o, text: e.target.value } : o);
                            updateQuestion(q.id, { options: newOpts });
                          }}
                        />
                        <Button size="sm" variant="ghost" onClick={() => {
                          const newOpts = q.options?.filter(o => o.id !== opt.id);
                          updateQuestion(q.id, { options: newOpts });
                        }}>&times;</Button>
                      </div>
                    ))}
                    <Button size="sm" variant="ghost" className="text-indigo-600" onClick={() => {
                      const newId = Math.random().toString(36).substr(2, 5);
                      updateQuestion(q.id, { options: [...(q.options || []), { id: newId, text: `Option ${(q.options?.length || 0) + 1}` }] });
                    }}>+ Add Option</Button>
                  </div>
                )}

                {q.type === QuestionType.TRUE_FALSE && (
                  <div>
                    <label className="text-sm font-semibold text-slate-700 block mb-2">Correct Answer</label>
                    <div className="flex gap-2">
                      {['true', 'false'].map(val => (
                        <button 
                          key={val}
                          className={`px-4 py-2 rounded-lg border capitalize ${q.correctAnswers[0] === val ? 'bg-indigo-600 text-white' : 'bg-slate-50'}`}
                          onClick={() => updateQuestion(q.id, { correctAnswers: [val] })}
                        >
                          {val}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {q.type === QuestionType.FILL_IN_THE_BLANK && (
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700 block">Accepted Answers (One per line)</label>
                    <textarea 
                      className="w-full p-2 border rounded-md text-sm"
                      placeholder="e.g. Gravity&#10;Gravitation"
                      value={q.correctAnswers.join('\n')}
                      onChange={(e) => updateQuestion(q.id, { correctAnswers: e.target.value.split('\n').filter(x => x.trim()) })}
                    />
                  </div>
                )}

                {q.type === QuestionType.SUBJECTIVE && (
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700 block">Reference Answer</label>
                    <textarea 
                      className="w-full p-2 border rounded-md text-sm"
                      rows={3}
                      value={q.subjectiveReference || ''}
                      onChange={(e) => updateQuestion(q.id, { subjectiveReference: e.target.value })}
                      placeholder="Provide the ideal answer for student reference..."
                    />
                  </div>
                )}

                <div className="pt-2">
                  <label className="text-sm font-semibold text-slate-700 block mb-1">Points / Score</label>
                  <input 
                    type="number" 
                    className="w-24 p-2 border rounded-md"
                    value={q.points}
                    onChange={(e) => updateQuestion(q.id, { points: parseInt(e.target.value) || 0 })}
                  />
                </div>
              </div>
            </div>
          ))
        )}
      </section>

      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 p-4 shadow-lg z-10 flex justify-center gap-4">
        <Button variant="ghost" onClick={onCancel}>Discard Changes</Button>
        <Button variant="primary" className="px-12" onClick={handleSave}>Save Quiz Set</Button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, UserAnswers, QuestionType, GradeResult } from '../types';
import { Button } from './Button';
import { QuestionRenderer } from './QuestionRenderer';

interface QuizTakerProps {
  quiz: QuizSet;
  onExit: () => void;
}

export const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, onExit }) => {
  const [answers, setAnswers] = useState<UserAnswers>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [grades, setGrades] = useState<GradeResult[]>([]);

  const handleAnswerChange = (qId: string, value: string | string[]) => {
    setAnswers(prev => ({ ...prev, [qId]: value }));
  };

  const calculateGrade = () => {
    const results: GradeResult[] = quiz.questions.map(q => {
      const userAns = answers[q.id];
      let isCorrect = false;
      let score = 0;

      switch (q.type) {
        case QuestionType.SINGLE_CHOICE:
        case QuestionType.TRUE_FALSE:
          isCorrect = userAns === q.correctAnswers[0];
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.MULTIPLE_CHOICE:
          const sortedCorrect = [...q.correctAnswers].sort().join(',');
          const sortedUser = Array.isArray(userAns) ? [...userAns].sort().join(',') : '';
          isCorrect = sortedCorrect === sortedUser;
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.FILL_IN_THE_BLANK:
          const normalizedUser = (userAns as string || '').trim().toLowerCase();
          isCorrect = q.correctAnswers.some(ans => ans.trim().toLowerCase() === normalizedUser);
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.SUBJECTIVE:
          isCorrect = true; // Subjective always counts as "completed" but needs manual checking
          score = 0; // Not auto-graded
          break;
      }

      return {
        questionId: q.id,
        isCorrect,
        score,
        maxScore: q.points,
      };
    });

    setGrades(results);
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const totalScore = grades.reduce((acc, g) => acc + g.score, 0);
  const maxPossible = quiz.questions.reduce((acc, q) => q.type !== QuestionType.SUBJECTIVE ? acc + q.points : acc, 0);

  if (isSubmitted) {
    return (
      <div className="max-w-4xl mx-auto pb-20">
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 mb-8 text-center">
          <h2 className="text-3xl font-bold text-slate-800 mb-2">Quiz Results</h2>
          <p className="text-slate-500 mb-6">{quiz.title}</p>

          <div className="flex justify-center gap-12 mb-8">
            <div>
              <div className="text-4xl font-extrabold text-indigo-600">{totalScore}</div>
              <div className="text-sm text-slate-400 font-medium">Auto-graded Score</div>
            </div>
            <div>
              <div className="text-4xl font-extrabold text-slate-700">{maxPossible}</div>
              <div className="text-sm text-slate-400 font-medium">Total Objective Points</div>
            </div>
          </div>

          <Button variant="primary" onClick={onExit}>Back to Library</Button>
        </div>

        <div className="space-y-6">
          {quiz.questions.map((q, idx) => {
            const grade = grades.find(g => g.questionId === q.id);
            return (
              <div key={q.id} className="relative">
                <QuestionRenderer
                  question={q}
                  index={idx}
                  answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
                  onChange={() => {}}
                  isGraded={true}
                />
                <div className={`mt-3 p-4 rounded-xl border ${grade?.isCorrect || q.type === QuestionType.SUBJECTIVE ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
                   <div className="flex justify-between items-center mb-2">
                     <span className="font-bold">
                       {q.type === QuestionType.SUBJECTIVE ? 'Subjective Question (Self-Review)' : (grade?.isCorrect ? '✓ Correct' : '✗ Incorrect')}
                     </span>
                     <span className="text-sm">
                       Score: {grade?.score} / {grade?.maxScore}
                     </span>
                   </div>

                   {q.type !== QuestionType.SUBJECTIVE && (
                     <div className="text-sm">
                        <span className="font-semibold">Correct Answer(s):</span> {
                          q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE
                            ? q.options?.filter(o => q.correctAnswers.includes(o.id)).map(o => o.text).join(', ')
                            : q.correctAnswers.join(' / ')
                        }
                     </div>
                   )}

                   {q.type === QuestionType.SUBJECTIVE && (
                     <div className="space-y-2 text-sm">
                        <div><span className="font-semibold">Your Answer:</span> {answers[q.id] || '(No answer provided)'}</div>
                        <div className="p-3 bg-white rounded border border-emerald-200 mt-2">
                          <span className="font-semibold block mb-1">Reference Answer:</span>
                          <p className="whitespace-pre-wrap">{q.subjectiveReference || 'No reference answer provided.'}</p>
                        </div>
                     </div>
                   )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-20">
      <div className="flex justify-between items-center mb-8 sticky top-0 bg-slate-50/90 backdrop-blur-md py-4 z-20">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">{quiz.title}</h1>
          <p className="text-sm text-slate-500">{quiz.questions.length} questions total</p>
        </div>
        <div className="flex gap-3">
          <Button variant="ghost" onClick={onExit}>Exit</Button>
          <Button variant="primary" className="px-8 shadow-indigo-200 shadow-lg" onClick={calculateGrade}>Submit Quiz</Button>
        </div>
      </div>

      <div className="space-y-8">
        {quiz.questions.map((q, idx) => (
          <QuestionRenderer
            key={q.id}
            question={q}
            index={idx}
            answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
            onChange={(val) => handleAnswerChange(q.id, val)}
          />
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [activeQuizId, setActiveQuizId] = useState<string | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  // Save to localStorage whenever quizzes change
  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setActiveQuizId(null);
  };

  const handleImport = () => {
    const decoded = decodeQuizKey(importKey);
    if (decoded) {
      // Check if ID already exists to prevent duplicates
      if (quizzes.some(q => q.id === decoded.id)) {
        alert("This quiz is already in your library.");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        alert(`Successfully imported: ${decoded.title}`);
      }
    } else {
      alert("Invalid share key. Please check and try again.");
    }
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this quiz?")) {
      setQuizzes(quizzes.filter(q => q.id !== id));
    }
  };

  const renderHome = () => (
    <div className="space-y-12">
      {/* Header Section */}
      <section className="text-center py-12 px-6 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl text-white shadow-xl shadow-indigo-100">
        <h1 className="text-4xl md:text-5xl font-extrabold mb-4">Master Your Knowledge</h1>
        <p className="text-indigo-100 text-lg mb-8 max-w-2xl mx-auto">Create custom self-test sets, import community shared tests, and track your progress with professional auto-grading.</p>
        <div className="flex flex-col sm:flex-row justify-center gap-4">
          <Button size="lg" variant="success" className="shadow-lg" onClick={() => setCurrentView('CREATE')}>Create New Quiz</Button>
          <div className="flex border border-white/20 rounded-lg overflow-hidden bg-white/10 backdrop-blur-sm p-1">
            <input 
              type="text" 
              placeholder="Paste Share Key..." 
              className="bg-transparent px-4 py-2 outline-none text-white placeholder-indigo-200 w-full"
              value={importKey}
              onChange={(e) => setImportKey(e.target.value)}
            />
            <Button variant="secondary" onClick={handleImport}>Import</Button>
          </div>
        </div>
      </section>

      {/* Library Section */}
      <section>
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-bold text-slate-800">My Library</h2>
          <span className="text-slate-400 text-sm font-medium">{quizzes.length} Quizzes Saved</span>
        </div>

        {quizzes.length === 0 ? (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <div className="mb-4 text-slate-300">
              <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.246.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            </div>
            <p className="text-slate-400 text-lg">Your library is empty. Create your first quiz above!</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { setActiveQuizId(id); setCurrentView('QUIZ'); }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-w-lg w-full shadow-2xl">
            <h3 className="text-xl font-bold text-slate-800 mb-2">Share Quiz Key</h3>
            <p className="text-slate-500 text-sm mb-6">Copy the code below and share it with others. They can import it into their library to take the test.</p>
            <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-6">
              <textarea 
                readOnly 
                className="w-full bg-transparent text-xs font-mono break-all focus:outline-none h-40"
                value={encodeQuizKey(quizzes.find(q => q.id === showShareModal)!)}
              />
            </div>
            <div className="flex gap-4">
              <Button variant="primary" className="flex-grow" onClick={() => {
                const key = encodeQuizKey(quizzes.find(q => q.id === showShareModal)!);
                navigator.clipboard.writeText(key);
                alert("Key copied to clipboard!");
              }}>Copy Key</Button>
              <Button variant="ghost" onClick={() => setShowShareModal(null)}>Close</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50">
      <nav className="bg-white border-b border-slate-200 h-16 sticky top-0 z-30 flex items-center px-6">
        <div className="max-w-7xl mx-auto w-full flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('HOME')}>
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
            </div>
            <span className="font-bold text-xl tracking-tight text-slate-800">Quiz<span className="text-indigo-600">Genius</span></span>
          </div>
          {currentView !== 'HOME' && (
             <Button variant="ghost" size="sm" onClick={() => setCurrentView('HOME')}>Back to Home</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {currentView === 'HOME' && renderHome()}
        {currentView === 'CREATE' && (
          <QuizEditor 
            onSave={handleSaveQuiz} 
            onCancel={() => setCurrentView('HOME')} 
          />
        )}
        {currentView === 'QUIZ' && activeQuizId && (
          <QuizTaker 
            quiz={quizzes.find(q => q.id === activeQuizId)!} 
            onExit={() => { setCurrentView('HOME'); setActiveQuizId(null); }} 
          />
        )}
      </main>

      <footer className="py-10 text-center text-slate-400 text-sm border-t border-slate-200 bg-white">
        <p>&copy; 2024 QuizGenius. Built for lifelong learners.</p>
      </footer>
    </div>
  );
};

export default App;

export enum QuestionType {
  SINGLE_CHOICE = 'SINGLE_CHOICE',
  MULTIPLE_CHOICE = 'MULTIPLE_CHOICE',
  FILL_IN_THE_BLANK = 'FILL_IN_THE_BLANK',
  TRUE_FALSE = 'TRUE_FALSE',
  SUBJECTIVE = 'SUBJECTIVE',
}

export interface Option {
  id: string;
  text: string;
}

export interface Question {
  id: string;
  type: QuestionType;
  text: string;
  options?: Option[]; 
  correctAnswers: string[]; 
  subjectiveReference?: string; 
  explanation?: string;
  points: number;
}

export interface QuizSet {
  id: string;
  title: string;
  description: string;
  createdAt: number;
  questions: Question[];
}

export type UserAnswers = Record<string, string | string[]>;

export interface GradeResult {
  questionId: string;
  isCorrect: boolean;
  score: number;
  maxScore: number;
  feedback?: string;
}

import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { Button } from './Button';
import { QuizSet, QuestionType } from '../types';

interface AIGeneratorProps {
  onGenerated: (quiz: Partial<QuizSet>) => void;
  onClose: () => void;
}

export const AIGenerator: React.FC<AIGeneratorProps> = ({ onGenerated, onClose }) => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('');

  const generateQuiz = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setStatus('Gemini is brainstorming questions...');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Create a comprehensive quiz about "${topic}". Include a mix of: 
          - Single choice (SINGLE_CHOICE)
          - Multiple choice (MULTIPLE_CHOICE)
          - Fill in the blank (FILL_IN_THE_BLANK)
          - True/False (TRUE_FALSE)
          - Subjective (SUBJECTIVE)
          Total around 5-8 questions. Provide standard answers for objective questions and a reference answer for subjective ones.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              questions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    type: { type: Type.STRING, description: "One of: SINGLE_CHOICE, MULTIPLE_CHOICE, FILL_IN_THE_BLANK, TRUE_FALSE, SUBJECTIVE" },
                    text: { type: Type.STRING },
                    points: { type: Type.NUMBER },
                    options: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: {
                          id: { type: Type.STRING },
                          text: { type: Type.STRING }
                        }
                      }
                    },
                    correctAnswers: { type: Type.ARRAY, items: { type: Type.STRING } },
                    subjectiveReference: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                  },
                  required: ["type", "text", "points", "correctAnswers"]
                }
              }
            },
            required: ["title", "description", "questions"]
          }
        }
      });

      const data = JSON.parse(response.text);
      // Ensure IDs are unique for the generated options
      const formattedQuestions = data.questions.map((q: any) => ({
        ...q,
        id: Math.random().toString(36).substr(2, 9),
        options: q.options?.map((o: any, idx: number) => ({ ...o, id: o.id || (idx + 1).toString() }))
      }));

      onGenerated({
        title: data.title,
        description: data.description,
        questions: formattedQuestions
      });
      onClose();
    } catch (error) {
      console.error(error);
      alert("AI Generation failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-2xl p-8 max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-10 h-10 bg-indigo-100 rounded-lg flex items-center justify-center text-indigo-600">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-800">AI Quiz Generator</h3>
            <p className="text-slate-500 text-sm">Let Gemini design your test set</p>
          </div>
        </div>

        <div className="space-y-4 mb-8">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Topic or Material</label>
            <textarea 
              className="w-full p-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none h-32"
              placeholder="e.g. World War II key events, Python Data Science, or paste some learning notes..."
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              disabled={loading}
            />
          </div>
          {loading && (
            <div className="flex items-center gap-3 text-indigo-600">
              <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <span className="text-sm font-medium">{status}</span>
            </div>
          )}
        </div>

        <div className="flex gap-3">
          <Button 
            className="flex-grow py-3" 
            variant="primary" 
            onClick={generateQuiz}
            isLoading={loading}
          >
            Start Magic Generation
          </Button>
          <Button variant="ghost" onClick={onClose} disabled={loading}>Cancel</Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, Question, QuestionType, Option } from '../types';
import { Button } from './Button';
import { AIGenerator } from './AIGenerator';

interface QuizEditorProps {
  onSave: (quiz: QuizSet) => void;
  onCancel: () => void;
  initialQuiz?: QuizSet;
}

export const QuizEditor: React.FC<QuizEditorProps> = ({ onSave, onCancel, initialQuiz }) => {
  const [title, setTitle] = useState(initialQuiz?.title || '');
  const [description, setDescription] = useState(initialQuiz?.description || '');
  const [questions, setQuestions] = useState<Question[]>(initialQuiz?.questions || []);
  const [isAiOpen, setIsAiOpen] = useState(false);

  const addQuestion = (type: QuestionType) => {
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      text: '',
      points: 5,
      correctAnswers: [],
      options: (type === QuestionType.SINGLE_CHOICE || type === QuestionType.MULTIPLE_CHOICE) 
        ? [{ id: '1', text: 'Option 1' }, { id: '2', text: 'Option 2' }] 
        : undefined,
    };
    setQuestions([...questions, newQuestion]);
  };

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter(q => q.id !== id));
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  const handleSave = () => {
    if (!title) {
      alert("Please provide a title");
      return;
    }
    onSave({
      id: initialQuiz?.id || Math.random().toString(36).substr(2, 9),
      title,
      description,
      createdAt: Date.now(),
      questions,
    });
  };

  const handleAiGenerated = (data: Partial<QuizSet>) => {
    if (data.title) setTitle(data.title);
    if (data.description) setDescription(data.description);
    if (data.questions) setQuestions(data.questions as Question[]);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32">
      {isAiOpen && (
        <AIGenerator onGenerated={handleAiGenerated} onClose={() => setIsAiOpen(false)} />
      )}

      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-800">{initialQuiz ? 'Edit Quiz' : 'Create New Quiz'}</h1>
        <Button variant="secondary" className="gap-2 border-indigo-200 text-indigo-600 hover:bg-indigo-50" onClick={() => setIsAiOpen(true)}>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          AI Magic Generate
        </Button>
      </div>

      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h2 className="text-lg font-bold text-slate-800 mb-6">General Information</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Quiz Title</label>
            <input 
              type="text" 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all font-medium"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="E.g., Mid-Term Physics Quiz"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
            <textarea 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What is this quiz about?"
            />
          </div>
        </div>
      </section>

      <section className="space-y-6">
        <div className="flex justify-between items-center border-b border-slate-200 pb-4">
          <h2 className="text-lg font-bold text-slate-800">Questions ({questions.length})</h2>
          <div className="flex flex-wrap gap-2">
            {Object.values(QuestionType).map(type => (
              <Button key={type} size="sm" variant="secondary" onClick={() => addQuestion(type)}>
                + {type.replace(/_/g, ' ').toLowerCase()}
              </Button>
            ))}
          </div>
        </div>

        {questions.length === 0 ? (
          <div className="text-center py-20 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
            <p className="text-slate-400">No questions added yet. Use AI or add manually.</p>
          </div>
        ) : (
          questions.map((q, idx) => (
            <div key={q.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 relative group transition-all hover:border-indigo-200">
              <button 
                onClick={() => removeQuestion(q.id)}
                className="absolute top-4 right-4 text-slate-300 hover:text-red-500 p-1 rounded-full hover:bg-red-50 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>

              <div className="mb-4">
                <div className="flex items-center gap-2 mb-2">
                   <span className="w-6 h-6 rounded bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold">{idx + 1}</span>
                   <label className="text-xs font-bold text-indigo-600 uppercase tracking-widest">{q.type.replace(/_/g, ' ')}</label>
                </div>
                <textarea
                  className="w-full p-3 bg-slate-50 rounded-lg border border-slate-200 font-medium outline-none focus:bg-white focus:ring-2 focus:ring-indigo-500 transition-all"
                  rows={2}
                  value={q.text}
                  onChange={(e) => updateQuestion(q.id, { text: e.target.value })}
                  placeholder="Enter the question text..."
                />
              </div>

              <div className="mt-4 space-y-4">
                {(q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE) && (
                  <div className="space-y-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase">Options & Correct Selection</label>
                    {q.options?.map(opt => (
                      <div key={opt.id} className="flex items-center gap-3">
                        <input 
                          type={q.type === QuestionType.SINGLE_CHOICE ? "radio" : "checkbox"} 
                          checked={q.correctAnswers.includes(opt.id)}
                          onChange={() => {
                            if (q.type === QuestionType.SINGLE_CHOICE) {
                              updateQuestion(q.id, { correctAnswers: [opt.id] });
                            } else {
                              const news = q.correctAnswers.includes(opt.id) 
                                ? q.correctAnswers.filter(id => id !== opt.id)
                                : [...q.correctAnswers, opt.id];
                              updateQuestion(q.id, { correctAnswers: news });
                            }
                          }}
                        />
                        <input 
                          type="text" 
                          className="flex-grow p-2 rounded-md border border-slate-200 text-sm bg-white"
                          value={opt.text}
                          onChange={(e) => {
                            const newOpts = q.options?.map(o => o.id === opt.id ? { ...o, text: e.target.value } : o);
                            updateQuestion(q.id, { options: newOpts });
                          }}
                        />
                        <button className="text-slate-300 hover:text-red-500" onClick={() => {
                          const newOpts = q.options?.filter(o => o.id !== opt.id);
                          updateQuestion(q.id, { options: newOpts });
                        }}>&times;</button>
                      </div>
                    ))}
                    <button className="text-xs font-bold text-indigo-600 hover:underline" onClick={() => {
                      const newId = Math.random().toString(36).substr(2, 5);
                      updateQuestion(q.id, { options: [...(q.options || []), { id: newId, text: `Option ${(q.options?.length || 0) + 1}` }] });
                    }}>+ Add Option</button>
                  </div>
                )}

                {q.type === QuestionType.TRUE_FALSE && (
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-3">Correct Answer</label>
