import React, { useState } from 'react';
import { QuizSet, Question, QuestionType, Option } from '../types';
import { Button } from './Button';
import { AIGenerator } from './AIGenerator';
import { JSONImporter } from './JSONImporter';

interface QuizEditorProps {
  onSave: (quiz: QuizSet) => void;
  onCancel: () => void;
  initialQuiz?: QuizSet;
}

export const QuizEditor: React.FC<QuizEditorProps> = ({ onSave, onCancel, initialQuiz }) => {
  const [title, setTitle] = useState(initialQuiz?.title || '');
  const [description, setDescription] = useState(initialQuiz?.description || '');
  const [questions, setQuestions] = useState<Question[]>(initialQuiz?.questions || []);
  const [isAiOpen, setIsAiOpen] = useState(false);
  const [isJsonOpen, setIsJsonOpen] = useState(false);

  const addQuestion = (type: QuestionType) => {
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      text: '',
      points: 5,
      correctAnswers: [],
      options: (type === QuestionType.SINGLE_CHOICE || type === QuestionType.MULTIPLE_CHOICE) 
        ? [{ id: '1', text: 'Option 1' }, { id: '2', text: 'Option 2' }] 
        : undefined,
    };
    setQuestions([...questions, newQuestion]);
  };

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter(q => q.id !== id));
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  const handleSave = () => {
    if (!title) {
      alert("Please provide a title");
      return;
    }
    onSave({
      id: initialQuiz?.id || Math.random().toString(36).substr(2, 9),
      title,
      description,
      createdAt: Date.now(),
      questions,
    });
  };

  const handleDataImported = (data: Partial<QuizSet>) => {
    if (data.title) setTitle(data.title);
    if (data.description) setDescription(data.description);
    if (data.questions) {
      const formatted = data.questions.map(q => ({
        ...q,
        id: q.id || Math.random().toString(36).substr(2, 9),
      })) as Question[];
      setQuestions(formatted);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32">
      {isAiOpen && (
        <AIGenerator onGenerated={handleDataImported} onClose={() => setIsAiOpen(false)} />
      )}

      {isJsonOpen && (
        <JSONImporter onImport={handleDataImported} onClose={() => setIsJsonOpen(false)} />
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h1 className="text-2xl font-bold text-slate-800">{initialQuiz ? 'Edit Quiz' : 'Create New Quiz'}</h1>
        <div className="flex gap-2">
          <Button variant="secondary" size="sm" className="gap-2 border-indigo-200 text-indigo-600 hover:bg-indigo-50" onClick={() => setIsAiOpen(true)}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
            AI Magic Generate
          </Button>
          <Button variant="secondary" size="sm" className="gap-2" onClick={() => setIsJsonOpen(true)}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" /></svg>
            Import JSON
          </Button>
        </div>
      </div>

      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h2 className="text-lg font-bold text-slate-800 mb-6">General Information</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Quiz Title</label>
            <input 
              type="text" 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all font-medium"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="E.g., Mid-Term Physics Quiz"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
            <textarea 
              className="w-full p-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What is this quiz about?"
            />
          </div>
        </div>
      </section>

      <section className="space-y-6">
        <div className="flex justify-between items-center border-b border-slate-200 pb-4">
          <h2 className="text-lg font-bold text-slate-800">Questions ({questions.length})</h2>
          <div className="flex flex-wrap gap-2">
            {Object.values(QuestionType).map(type => (
              <Button key={type} size="sm" variant="secondary" onClick={() => addQuestion(type)}>
                + {type.replace(/_/g, ' ').toLowerCase()}
              </Button>
            ))}
          </div>
        </div>

        {questions.length === 0 ? (
          <div className="text-center py-20 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
            <p className="text-slate-400">No questions added yet. Use AI, JSON, or add manually.</p>
          </div>
        ) : (
          questions.map((q, idx) => (
            <div key={q.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 relative group transition-all hover:border-indigo-200">
              <button 
                onClick={() => removeQuestion(q.id)}
                className="absolute top-4 right-4 text-slate-300 hover:text-red-500 p-1 rounded-full hover:bg-red-50 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>

              <div className="mb-4">
                <div className="flex items-center gap-2 mb-2">
                   <span className="w-6 h-6 rounded bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold">{idx + 1}</span>
                   <label className="text-xs font-bold text-indigo-600 uppercase tracking-widest">{q.type.replace(/_/g, ' ')}</label>
                </div>
                <textarea
                  className="w-full p-3 bg-slate-50 rounded-lg border border-slate-200 font-medium outline-none focus:bg-white focus:ring-2 focus:ring-indigo-500 transition-all"
                  rows={2}
                  value={q.text}
                  onChange={(e) => updateQuestion(q.id, { text: e.target.value })}
                  placeholder="Enter the question text..."
                />
              </div>

              <div className="mt-4 space-y-4">
                {(q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE) && (
                  <div className="space-y-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase">Options & Correct Selection</label>
                    {q.options?.map(opt => (
                      <div key={opt.id} className="flex items-center gap-3">
                        <input 
                          type={q.type === QuestionType.SINGLE_CHOICE ? "radio" : "checkbox"} 
                          checked={q.correctAnswers.includes(opt.id)}
                          onChange={() => {
                            if (q.type === QuestionType.SINGLE_CHOICE) {
                              updateQuestion(q.id, { correctAnswers: [opt.id] });
                            } else {
                              const news = q.correctAnswers.includes(opt.id) 
                                ? q.correctAnswers.filter(id => id !== opt.id)
                                : [...q.correctAnswers, opt.id];
                              updateQuestion(q.id, { correctAnswers: news });
                            }
                          }}
                        />
                        <input 
                          type="text" 
                          className="flex-grow p-2 rounded-md border border-slate-200 text-sm bg-white"
                          value={opt.text}
                          onChange={(e) => {
                            const newOpts = q.options?.map(o => o.id === opt.id ? { ...o, text: e.target.value } : o);
                            updateQuestion(q.id, { options: newOpts });
                          }}
                        />
                        <button className="text-slate-300 hover:text-red-500" onClick={() => {
                          const newOpts = q.options?.filter(o => o.id !== opt.id);
                          updateQuestion(q.id, { options: newOpts });
                        }}>&times;</button>
                      </div>
                    ))}
                    <button className="text-xs font-bold text-indigo-600 hover:underline" onClick={() => {
                      const newId = Math.random().toString(36).substr(2, 5);
                      updateQuestion(q.id, { options: [...(q.options || []), { id: newId, text: `Option ${(q.options?.length || 0) + 1}` }] });
                    }}>+ Add Option</button>
                  </div>
                )}

                {q.type === QuestionType.TRUE_FALSE && (
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-3">Correct Answer</label>
                    <div className="flex gap-2">
                      {['true', 'false'].map(val => (
                        <button 
                          key={val}
                          className={`flex-1 py-2 rounded-lg border font-medium capitalize transition-all ${q.correctAnswers[0] === val ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-600 border-slate-200'}`}
                          onClick={() => updateQuestion(q.id, { correctAnswers: [val] })}
                        >
                          {val}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {q.type === QuestionType.FILL_IN_THE_BLANK && (
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Accepted Answers (One per line)</label>
                    <textarea 
                      className="w-full p-2 border rounded-md text-sm bg-white"
                      placeholder="e.g. Gravity&#10;Gravitation"
                      rows={2}
                      value={q.correctAnswers.join('\n')}
                      onChange={(e) => updateQuestion(q.id, { correctAnswers: e.target.value.split('\n').filter(x => x.trim()) })}
                    />
                  </div>
                )}

                {q.type === QuestionType.SUBJECTIVE && (
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Reference Answer</label>
                    <textarea 
                      className="w-full p-2 border rounded-md text-sm bg-white"
                      rows={3}
                      value={q.subjectiveReference || ''}
                      onChange={(e) => updateQuestion(q.id, { subjectiveReference: e.target.value })}
                      placeholder="Provide the ideal answer for student reference..."
                    />
                  </div>
                )}

                <div className="flex items-center gap-4 pt-2 border-t border-slate-100">
                  <div className="flex items-center gap-2">
                    <label className="text-xs font-bold text-slate-400 uppercase">Points:</label>
                    <input 
                      type="number" 
                      className="w-16 p-1 border rounded text-sm text-center font-bold text-indigo-600"
                      value={q.points}
                      onChange={(e) => updateQuestion(q.id, { points: parseInt(e.target.value) || 0 })}
                    />
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </section>

      <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-slate-200 p-4 shadow-2xl z-40 flex justify-center gap-4">
        <Button variant="ghost" onClick={onCancel}>Discard</Button>
        <Button variant="primary" className="px-12 shadow-lg shadow-indigo-100" onClick={handleSave}>Save Quiz Set</Button>
      </div>
    </div>
  );
};
</app_code>
<app_code>
import React, { useState } from 'react';
import { QuizSet, UserAnswers, QuestionType, GradeResult } from '../types';
import { Button } from './Button';
import { QuestionRenderer } from './QuestionRenderer';

interface QuizTakerProps {
  quiz: QuizSet;
  onExit: () => void;
}

export const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, onExit }) => {
  const [answers, setAnswers] = useState<UserAnswers>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [grades, setGrades] = useState<GradeResult[]>([]);

  const handleAnswerChange = (qId: string, value: string | string[]) => {
    setAnswers(prev => ({ ...prev, [qId]: value }));
  };

  const calculateGrade = () => {
    const results: GradeResult[] = quiz.questions.map(q => {
      const userAns = answers[q.id];
      let isCorrect = false;
      let score = 0;

      switch (q.type) {
        case QuestionType.SINGLE_CHOICE:
        case QuestionType.TRUE_FALSE:
          isCorrect = userAns === q.correctAnswers[0];
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.MULTIPLE_CHOICE:
          const sortedCorrect = [...q.correctAnswers].sort().join(',');
          const sortedUser = Array.isArray(userAns) ? [...userAns].sort().join(',') : '';
          isCorrect = sortedCorrect === sortedUser;
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.FILL_IN_THE_BLANK:
          const normalizedUser = (userAns as string || '').trim().toLowerCase();
          isCorrect = q.correctAnswers.some(ans => ans.trim().toLowerCase() === normalizedUser);
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.SUBJECTIVE:
          isCorrect = true; // Subjective always counts as "completed" but needs manual checking
          score = 0; // Not auto-graded
          break;
      }

      return {
        questionId: q.id,
        isCorrect,
        score,
        maxScore: q.points,
      };
    });

    setGrades(results);
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const totalScore = grades.reduce((acc, g) => acc + g.score, 0);
  const maxPossible = quiz.questions.reduce((acc, q) => q.type !== QuestionType.SUBJECTIVE ? acc + q.points : acc, 0);

  if (isSubmitted) {
    return (
      <div className="max-w-4xl mx-auto pb-20">
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 mb-8 text-center">
          <h2 className="text-3xl font-bold text-slate-800 mb-2">Quiz Results</h2>
          <p className="text-slate-500 mb-6">{quiz.title}</p>

          <div className="flex justify-center gap-12 mb-8">
            <div>
              <div className="text-4xl font-extrabold text-indigo-600">{totalScore}</div>
              <div className="text-sm text-slate-400 font-medium">Auto-graded Score</div>
            </div>
            <div>
              <div className="text-4xl font-extrabold text-slate-700">{maxPossible}</div>
              <div className="text-sm text-slate-400 font-medium">Total Objective Points</div>
            </div>
          </div>

          <Button variant="primary" onClick={onExit}>Back to Library</Button>
        </div>

        <div className="space-y-6">
          {quiz.questions.map((q, idx) => {
            const grade = grades.find(g => g.questionId === q.id);
            return (
              <div key={q.id} className="relative">
                <QuestionRenderer
                  question={q}
                  index={idx}
                  answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
                  onChange={() => {}}
                  isGraded={true}
                />
                <div className={`mt-3 p-4 rounded-xl border ${grade?.isCorrect || q.type === QuestionType.SUBJECTIVE ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
                   <div className="flex justify-between items-center mb-2">
                     <span className="font-bold">
                       {q.type === QuestionType.SUBJECTIVE ? 'Subjective Question (Self-Review)' : (grade?.isCorrect ? '✓ Correct' : '✗ Incorrect')}
                     </span>
                     <span className="text-sm">
                       Score: {grade?.score} / {grade?.maxScore}
                     </span>
                   </div>

                   {q.type !== QuestionType.SUBJECTIVE && (
                     <div className="text-sm">
                        <span className="font-semibold">Correct Answer(s):</span> {
                          q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE
                            ? q.options?.filter(o => q.correctAnswers.includes(o.id)).map(o => o.text).join(', ')
                            : q.correctAnswers.join(' / ')
                        }
                     </div>
                   )}

                   {q.type === QuestionType.SUBJECTIVE && (
                     <div className="space-y-2 text-sm">
                        <div><span className="font-semibold">Your Answer:</span> {answers[q.id] || '(No answer provided)'}</div>
                        <div className="p-3 bg-white rounded border border-emerald-200 mt-2">
                          <span className="font-semibold block mb-1">Reference Answer:</span>
                          <p className="whitespace-pre-wrap">{q.subjectiveReference || 'No reference answer provided.'}</p>
                        </div>
                     </div>
                   )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-20">
      <div className="flex justify-between items-center mb-8 sticky top-0 bg-slate-50/90 backdrop-blur-md py-4 z-20">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">{quiz.title}</h1>
          <p className="text-sm text-slate-500">{quiz.questions.length} questions total</p>
        </div>
        <div className="flex gap-3">
          <Button variant="ghost" onClick={onExit}>Exit</Button>
          <Button variant="primary" className="px-8 shadow-indigo-200 shadow-lg" onClick={calculateGrade}>Submit Quiz</Button>
        </div>
      </div>

      <div className="space-y-8">
        {quiz.questions.map((q, idx) => (
          <QuestionRenderer
            key={q.id}
            question={q}
            index={idx}
            answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
            onChange={(val) => handleAnswerChange(q.id, val)}
          />
        ))}
      </div>
    </div>
  );
};
</app_code>
<app_code>
import React, { useState, useEffect, useRef } from 'react';
import QRCode from 'qrcode';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { QRScanner } from './components/QRScanner';
import { DevDocs } from './components/DevDocs';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [activeQuizId, setActiveQuizId] = useState<string | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);
  const [showDevDocs, setShowDevDocs] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string>('');
  const [isImporting, setIsImporting] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const qrCanvasRef = useRef<HTMLCanvasElement>(null);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  // Save to localStorage whenever quizzes change
  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  // Handle generating share key and QR Code when modal opens
  useEffect(() => {
    if (showShareModal) {
      const quiz = quizzes.find(q => q.id === showShareModal);
      if (quiz) {
        encodeQuizKey(quiz).then(key => {
          setGeneratedKey(key);
          if (qrCanvasRef.current) {
            QRCode.toCanvas(qrCanvasRef.current, key, {
              width: 256,
              margin: 2,
              color: {
                dark: '#4f46e5', // Indigo-600
                light: '#ffffff'
              }
            }, (error) => {
              if (error) console.error("QR Code generation error", error);
            });
          }
        });
      }
    } else {
      setGeneratedKey('');
    }
  }, [showShareModal, quizzes]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setActiveQuizId(null);
  };

  const performImport = async (key: string) => {
    if (!key.trim()) return;
    setIsImporting(true);
    const decoded = await decodeQuizKey(key.trim());
    setIsImporting(false);

    if (decoded) {
      if (quizzes.some(q => q.id === decoded.id)) {
        alert("This quiz is already in your library.");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        alert(`Successfully imported: ${decoded.title}`);
        return true;
      }
    } else {
      alert("Invalid share key or QR code. The data might be corrupted.");
    }
    return false;
  };

  const handleImport = () => performImport(importKey);

  const onQRScanSuccess = async (decodedText: string) => {
    setIsScanning(false);
    await performImport(decodedText);
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this quiz?")) {
      setQuizzes(quizzes.filter(q => q.id !== id));
    }
  };

  const renderHome = () => (
    <div className="space-y-12">
      {/* Header Section */}
      <section className="text-center py-12 px-6 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl text-white shadow-xl shadow-indigo-100">
        <h1 className="text-4xl md:text-5xl font-extrabold mb-4">Master Your Knowledge</h1>
        <p className="text-indigo-100 text-lg mb-8 max-w-2xl mx-auto">Create custom self-test sets, import community shared tests, and track your progress with professional auto-grading.</p>

        <div className="flex flex-col items-center gap-6">
          <div className="flex flex-col sm:flex-row justify-center gap-4 w-full max-w-2xl">
            <Button size="lg" variant="success" className="shadow-lg px-8" onClick={() => setCurrentView('CREATE')}>Create New Quiz</Button>

            <div className="flex-grow flex border border-white/20 rounded-xl overflow-hidden bg-white/10 backdrop-blur-sm p-1">
              <input 
                type="text" 
                placeholder="Paste Share Key..." 
                className="bg-transparent px-4 py-2 outline-none text-white placeholder-indigo-200 w-full"
                value={importKey}
                onChange={(e) => setImportKey(e.target.value)}
              />
              <Button variant="secondary" className="rounded-lg mr-1" onClick={handleImport} isLoading={isImporting}>Import</Button>
              <Button 
                variant="ghost" 
                className="bg-white/20 text-white hover:bg-white/30 rounded-lg p-2" 
                title="Scan QR Code"
                onClick={() => setIsScanning(true)}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
              </Button>
            </div>
          </div>
          <p className="text-xs text-indigo-200">Tip: Click the QR icon to import via camera scanning</p>
        </div>
      </section>

      {/* Library Section */}
      <section>
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-bold text-slate-800">My Library</h2>
          <span className="text-slate-400 text-sm font-medium">{quizzes.length} Quizzes Saved</span>
        </div>

        {quizzes.length === 0 ? (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <div className="mb-4 text-slate-300">
              <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.246.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            </div>
            <p className="text-slate-400 text-lg">Your library is empty. Create your first quiz above!</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { setActiveQuizId(id); setCurrentView('QUIZ'); }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>

      {/* QR Scanner */}
      {isScanning && (
        <QRScanner onScanSuccess={onQRScanSuccess} onClose={() => setIsScanning(false)} />
      )}

      {/* Dev Docs */}
      {showDevDocs && (
        <DevDocs onClose={() => setShowDevDocs(false)} />
      )}

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
            <h3 className="text-xl font-bold text-slate-800 mb-2 text-center">Share This Quiz</h3>
            <p className="text-slate-500 text-sm mb-6 text-center">Others can scan this code or use the text key to import.</p>

            <div className="flex justify-center mb-6">
              <div className="p-4 bg-white border-4 border-indigo-50 rounded-2xl">
                <canvas ref={qrCanvasRef} className="w-64 h-64"></canvas>
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-6 relative group">
              {generatedKey ? (
                <>
                  <textarea 
                    readOnly 
                    className="w-full bg-transparent text-[10px] font-mono break-all focus:outline-none h-20 resize-none"
                    value={generatedKey}
                  />
                  <div className="absolute inset-0 bg-slate-900/5 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
