/**
 * Converts a Uint8Array to a Base64 string safely
 */
const uint8ArrayToBase64 = (array: Uint8Array): string => {
  let binary = '';
  const len = array.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(array[i]);
  }
  return btoa(binary);
};

/**
 * Converts a Base64 string back to a Uint8Array
 */
const base64ToUint8Array = (base64: string): Uint8Array => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

/**
 * Consumes a ReadableStream and returns a Uint8Array.
 * This avoids 'Failed to fetch' errors associated with using the Response object to consume streams.
 */
const consumeStream = async (stream: ReadableStream<Uint8Array>): Promise<Uint8Array> => {
  const reader = stream.getReader();
  const chunks: Uint8Array[] = [];
  let totalLength = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    totalLength += value.length;
  }

  const result = new Uint8Array(totalLength);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
};

/**
 * Encodes a QuizSet into a Compressed Base64 string
 */
export const encodeQuizKey = async (quiz: QuizSet): Promise<string> => {
  try {
    const jsonStr = JSON.stringify(quiz);
    const uint8 = new TextEncoder().encode(jsonStr);

    // Using native CompressionStream (Deflate / ZLIB)
    // Cast to any to avoid TypeScript errors with SharedArrayBuffer vs ArrayBuffer in strict environments
    const stream = new Blob([uint8 as any]).stream();
    const compressionStream = new CompressionStream('deflate');
    const compressedStream = stream.pipeThrough(compressionStream);

    const compressedBuffer = await consumeStream(compressedStream);
    return uint8ArrayToBase64(compressedBuffer);
  } catch (e) {
    console.error("Failed to encode quiz key", e);
    return '';
  }
};

/**
 * Decodes a Compressed Share Key back into a QuizSet
 */
export const decodeQuizKey = async (key: string): Promise<QuizSet | null> => {
  try {
    const compressedData = base64ToUint8Array(key);

    // Using native DecompressionStream
    // Cast to any to avoid TypeScript errors with SharedArrayBuffer vs ArrayBuffer in strict environments
    const stream = new Blob([compressedData as any]).stream();
    const decompressionStream = new DecompressionStream('deflate');
    const decompressedStream = stream.pipeThrough(decompressionStream);

    const decompressedBuffer = await consumeStream(decompressedStream);
    const jsonStr = new TextDecoder().decode(decompressedBuffer);

    return JSON.parse(jsonStr) as QuizSet;
  } catch (e: any) {
    console.error("Failed to decode quiz key", e.message || e);
    return null;
  }
};

import React from 'react';
import { Question, QuestionType } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: string | string[];
  onChange: (value: string | string[]) => void;
  isGraded?: boolean;
  isConfused?: boolean;
  onToggleConfusion?: () => void;
}

export const QuestionRenderer: React.FC<QuestionRendererProps> = ({
  question,
  index,
  answer,
  onChange,
  isGraded = false,
  isConfused = false,
  onToggleConfusion
}) => {
  const handleSingleChoice = (optionId: string) => {
    if (isGraded) return;
    onChange(optionId);
  };

  const handleMultipleChoice = (optionId: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) ? answer : [];
    if (currentAnswers.includes(optionId)) {
      onChange(currentAnswers.filter(id => id !== optionId));
    } else {
      onChange([...currentAnswers, optionId]);
    }
  };

  const handleTrueFalse = (val: string) => {
    if (isGraded) return;
    onChange(val);
  };

  return (
    <div className={`p-6 rounded-xl bg-white border relative transition-all ${
      isGraded ? 'border-slate-200' : 'border-indigo-100 shadow-sm'
    } ${isConfused && !isGraded ? 'ring-2 ring-yellow-400 border-yellow-400' : ''}`}>

      {/* Confusion Toggle */}
      {!isGraded && onToggleConfusion && (
        <button
          onClick={(e) => {
            e.preventDefault();
            onToggleConfusion();
          }}
          title="Mark as confused / 标记为困惑"
          className={`absolute top-4 right-4 w-8 h-8 rounded-full flex items-center justify-center transition-all border ${
            isConfused 
              ? 'bg-yellow-400 text-white border-yellow-500 shadow-md scale-110' 
              : 'bg-white text-slate-300 border-slate-200 hover:text-yellow-500 hover:border-yellow-300'
          }`}
        >
          <span className="font-bold text-lg">?</span>
        </button>
      )}

      {/* Confused Indicator in Graded view */}
      {isGraded && isConfused && (
        <div className="absolute top-4 right-4 px-2 py-1 bg-yellow-100 text-yellow-700 text-[10px] font-bold rounded uppercase tracking-wider flex items-center gap-1">
          <span className="text-sm">?</span> Marked Confused
        </div>
      )}

      <div className="flex items-start gap-4 mb-4">
        <span className="flex-shrink-0 w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold text-sm">
          {index + 1}
        </span>
        <div className="flex-grow pr-8">
          <div className="flex items-center gap-2 mb-1">
             <span className="text-xs font-bold uppercase tracking-wider text-slate-400">
               {question.type.replace(/_/g, ' ')}
             </span>
             <span className="text-xs text-slate-400">• {question.points} pts</span>
          </div>
          <h4 className="text-lg font-medium text-slate-800 whitespace-pre-wrap">{question.text}</h4>
        </div>
      </div>

      <div className="ml-12 space-y-3">
        {question.type === QuestionType.SINGLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              answer === opt.id 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="radio" 
              name={`q-${question.id}`} 
              checked={answer === opt.id}
              onChange={() => handleSingleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.MULTIPLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              Array.isArray(answer) && answer.includes(opt.id) 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="checkbox" 
              checked={Array.isArray(answer) && answer.includes(opt.id)}
              onChange={() => handleMultipleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.TRUE_FALSE && (
          <div className="flex gap-4">
            {['true', 'false'].map(val => (
              <button
                key={val}
                onClick={() => handleTrueFalse(val)}
                className={`flex-1 py-3 px-4 rounded-lg border font-medium capitalize transition-all ${
                  answer === val 
                    ? 'border-indigo-600 bg-indigo-600 text-white shadow-md' 
                    : 'border-slate-200 text-slate-600 hover:bg-slate-50'
                } ${isGraded ? 'pointer-events-none' : ''}`}
              >
                {val}
              </button>
            ))}
          </div>
        )}

        {question.type === QuestionType.FILL_IN_THE_BLANK && (
          <input
            type="text"
            placeholder="Type your answer here..."
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
            disabled={isGraded}
          />
        )}

        {question.type === QuestionType.SUBJECTIVE && (
          <textarea
            placeholder="Write your answer in detail..."
            rows={4}
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
            disabled={isGraded}
          />
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, UserAnswers, QuestionType, GradeResult } from '../types';
import { Button } from './Button';
import { QuestionRenderer } from './QuestionRenderer';

interface QuizTakerProps {
  quiz: QuizSet;
  onExit: () => void;
}

export const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, onExit }) => {
  const [answers, setAnswers] = useState<UserAnswers>({});
  const [confusedIds, setConfusedIds] = useState<Set<string>>(new Set());
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [grades, setGrades] = useState<GradeResult[]>([]);

  const handleAnswerChange = (qId: string, value: string | string[]) => {
    setAnswers(prev => ({ ...prev, [qId]: value }));
  };

  const toggleConfusion = (qId: string) => {
    setConfusedIds(prev => {
      const next = new Set(prev);
      if (next.has(qId)) next.delete(qId);
      else next.add(qId);
      return next;
    });
  };

  const isQuestionAnswered = (qId: string): boolean => {
    const val = answers[qId];
    if (val === undefined || val === null) return false;
    if (Array.isArray(val)) return val.length > 0;
    if (typeof val === 'string') return val.trim().length > 0;
    return false;
  };

  const calculateGrade = () => {
    const results: GradeResult[] = quiz.questions.map(q => {
      const userAns = answers[q.id];
      let isCorrect = false;
      let score = 0;

      switch (q.type) {
        case QuestionType.SINGLE_CHOICE:
        case QuestionType.TRUE_FALSE:
          isCorrect = userAns === q.correctAnswers[0];
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.MULTIPLE_CHOICE:
          const sortedCorrect = [...q.correctAnswers].sort().join(',');
          const sortedUser = Array.isArray(userAns) ? [...userAns].sort().join(',') : '';
          isCorrect = sortedCorrect === sortedUser;
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.FILL_IN_THE_BLANK:
          const normalizedUser = (userAns as string || '').trim().toLowerCase();
          isCorrect = q.correctAnswers.some(ans => ans.trim().toLowerCase() === normalizedUser);
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.SUBJECTIVE:
          isCorrect = true; // Subjective always counts as "completed" but needs manual checking
          score = 0; // Not auto-graded
          break;
      }

      return {
        questionId: q.id,
        isCorrect,
        score,
        maxScore: q.points,
      };
    });

    setGrades(results);
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToQuestion = (id: string) => {
    const el = document.getElementById(`q-container-${id}`);
    if (el) {
      const offset = 100;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = el.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  const answeredCount = quiz.questions.filter(q => isQuestionAnswered(q.id)).length;
  const progressPercent = Math.round((answeredCount / quiz.questions.length) * 100);

  const totalScore = grades.reduce((acc, g) => acc + g.score, 0);
  const maxPossible = quiz.questions.reduce((acc, q) => q.type !== QuestionType.SUBJECTIVE ? acc + q.points : acc, 0);

  const renderSidebar = () => (
    <aside className="w-full lg:w-72 lg:sticky lg:top-24 z-30 order-first lg:order-last">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden backdrop-blur-sm bg-white/90">
        <div className="p-5 border-b border-slate-100 bg-slate-50/50">
          <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-3">
            {isSubmitted ? 'Result Navigation' : 'Quiz Progress'}
          </h3>

          {!isSubmitted ? (
            <>
              <div className="flex items-center justify-between text-xs mb-2">
                <span className="text-slate-500 font-medium">{answeredCount} of {quiz.questions.length} Answered</span>
                <span className="text-indigo-600 font-bold">{progressPercent}%</span>
              </div>
              <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-indigo-600 transition-all duration-500 ease-out" 
                  style={{ width: `${progressPercent}%` }}
                ></div>
              </div>
            </>
          ) : (
            <div className="space-y-1">
              <div className="text-lg font-bold text-indigo-600">Score: {totalScore} / {maxPossible}</div>
              <p className="text-[10px] text-slate-400">Click a number to review details</p>
            </div>
          )}
        </div>

        <div className="p-5">
          <div className="grid grid-cols-5 gap-2 mb-6">
            {quiz.questions.map((q, idx) => {
              const answered = isQuestionAnswered(q.id);
              const confused = confusedIds.has(q.id);
              const grade = grades.find(g => g.questionId === q.id);

              let statusClass = "bg-slate-100 text-slate-400 hover:bg-slate-200";

              if (isSubmitted) {
                if (confused) {
                  statusClass = "bg-yellow-400 text-white shadow-md";
                } else if (q.type === QuestionType.SUBJECTIVE) {
                  statusClass = "bg-indigo-500 text-white shadow-md";
                } else if (grade?.isCorrect) {
                  statusClass = "bg-emerald-500 text-white shadow-md";
                } else {
                  statusClass = "bg-red-500 text-white shadow-md";
                }
              } else {
                if (confused) {
                  statusClass = "bg-yellow-400 text-white shadow-md";
                } else if (answered) {
                  statusClass = "bg-indigo-600 text-white shadow-md";
                }
              }

              return (
                <button
                  key={q.id}
                  onClick={() => scrollToQuestion(q.id)}
                  title={`Question ${idx + 1}`}
                  className={`h-10 w-full rounded-lg text-sm font-bold transition-all ${statusClass}`}
                >
                  {idx + 1}
                </button>
              );
            })}
          </div>

          <div className="space-y-3">
            {!isSubmitted ? (
              <>
                <Button 
                  variant="primary" 
                  className="w-full py-3 shadow-lg shadow-indigo-100" 
                  onClick={calculateGrade}
                >
                  Submit Quiz
                </Button>
                <Button 
                  variant="ghost" 
                  className="w-full text-slate-500 hover:text-red-500 hover:bg-red-50" 
                  onClick={() => {
                    if(confirm("Are you sure you want to exit? Your progress will not be saved.")) {
                      onExit();
                    }
                  }}
                >
                  Exit Test
                </Button>
              </>
            ) : (
              <Button variant="primary" className="w-full py-3" onClick={onExit}>Finish Review</Button>
            )}
          </div>
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-100 text-[10px] space-y-2">
          <div className="flex items-center justify-center gap-4">
             <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-emerald-500"></span> Correct</div>
             <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-500"></span> Wrong</div>
             <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-yellow-400"></span> Confused</div>
          </div>
        </div>
      </div>
    </aside>
  );

  return (
    <div className="relative max-w-7xl mx-auto px-4 pb-20 flex flex-col lg:flex-row gap-8 items-start">
      {/* Quiz/Result Content */}
      <div className="w-full lg:max-w-4xl space-y-8">
        <div className="mb-8">
          <h1 className="text-3xl font-extrabold text-slate-800 mb-2">
            {isSubmitted ? 'Results: ' : ''}{quiz.title}
          </h1>
          <p className="text-slate-500">{quiz.description}</p>
        </div>

        <div className="space-y-12">
          {quiz.questions.map((q, idx) => {
            const grade = grades.find(g => g.questionId === q.id);
            return (
              <div key={q.id} id={`q-container-${q.id}`} className="space-y-4">
                <QuestionRenderer
                  question={q}
                  index={idx}
                  answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
                  onChange={(val) => handleAnswerChange(q.id, val)}
                  isGraded={isSubmitted}
                  isConfused={confusedIds.has(q.id)}
                  onToggleConfusion={() => toggleConfusion(q.id)}
                />

                {isSubmitted && (
                  <div className={`p-4 rounded-xl border ${grade?.isCorrect || q.type === QuestionType.SUBJECTIVE ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
                    <div className="flex justify-between items-center mb-2">
                      <span className="font-bold flex items-center gap-2">
                        {q.type === QuestionType.SUBJECTIVE ? 'Subjective Question (Self-Review)' : (grade?.isCorrect ? '✓ Correct' : '✗ Incorrect')}
                        {confusedIds.has(q.id) && <span className="bg-yellow-400 text-white text-[10px] px-2 py-0.5 rounded-full">Review Requested</span>}
                      </span>
                      <span className="text-sm">
                        Score: {grade?.score} / {grade?.maxScore}
                      </span>
                    </div>

                    {q.type !== QuestionType.SUBJECTIVE && (
                      <div className="text-sm">
                        <span className="font-semibold">Correct Answer(s):</span> {
                          q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE || q.type === QuestionType.TRUE_FALSE
                            ? q.options?.filter(o => q.correctAnswers.includes(o.id)).map(o => o.text).join(', ') || q.correctAnswers.join(', ')
                            : q.correctAnswers.join(' / ')
                        }
                      </div>
                    )}

                    {q.type === QuestionType.SUBJECTIVE && (
                      <div className="space-y-2 text-sm">
                        <div><span className="font-semibold">Your Answer:</span> {answers[q.id] || '(No answer provided)'}</div>
                        <div className="p-3 bg-white rounded border border-emerald-200 mt-2">
                          <span className="font-semibold block mb-1">Reference Answer:</span>
                          <p className="whitespace-pre-wrap">{q.subjectiveReference || 'No reference answer provided.'}</p>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {renderSidebar()}
    </div>
  );
};

import React from 'react';
import { QuizSet } from '../types';
import { Button } from './Button';

interface QuizCardProps {
  quiz: QuizSet;
  onStart: (id: string) => void;
  onRandomStart: (id: string) => void;
  onShare: (id: string) => void;
  onDelete: (id: string) => void;
}

export const QuizCard: React.FC<QuizCardProps> = ({ quiz, onStart, onRandomStart, onShare, onDelete }) => {
  return (
    <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-3">
        <h3 className="text-lg font-bold text-slate-800 line-clamp-1">{quiz.title}</h3>
        <span className="text-xs font-semibold px-2 py-1 bg-indigo-50 text-indigo-700 rounded-full">
          {quiz.questions.length} Questions
        </span>
      </div>
      <p className="text-slate-500 text-sm line-clamp-2 mb-6 h-10">
        {quiz.description || "No description provided."}
      </p>
      <div className="flex flex-wrap gap-2">
        <Button variant="primary" size="sm" onClick={() => onStart(quiz.id)}>Start Test</Button>
        <Button variant="secondary" size="sm" onClick={() => onRandomStart(quiz.id)}>Random N</Button>
        <Button variant="secondary" size="sm" onClick={() => onShare(quiz.id)}>Share Key</Button>
        <Button variant="ghost" size="sm" className="text-red-500 hover:text-red-600 hover:bg-red-50" onClick={() => onDelete(quiz.id)}>Delete</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import QRCode from 'qrcode';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { QRScanner } from './components/QRScanner';
import { DevDocs } from './components/DevDocs';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';

export default function App() {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [sessionQuiz, setSessionQuiz] = useState<QuizSet | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);
  const [showStartPrompt, setShowStartPrompt] = useState<QuizSet | null>(null);
  const [showRandomPrompt, setShowRandomPrompt] = useState<QuizSet | null>(null);
  const [randomN, setRandomN] = useState<number>(5);
  const [showDevDocs, setShowDevDocs] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string>('');
  const [qrError, setQrError] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const qrCanvasRef = useRef<HTMLCanvasElement>(null);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  // Save to localStorage whenever quizzes change
  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  // Handle generating share key when modal opens
  useEffect(() => {
    if (showShareModal) {
      const quiz = quizzes.find(q => q.id === showShareModal);
      if (quiz) {
        setQrError(null);
        encodeQuizKey(quiz).then(key => {
          setGeneratedKey(key);
        });
      }
    } else {
      setGeneratedKey('');
      setQrError(null);
    }
  }, [showShareModal, quizzes]);

  // Handle drawing the QR Code when the key is generated and canvas is available
  useEffect(() => {
    if (generatedKey && qrCanvasRef.current) {
      // Use Error Correction Level 'L' (Low) to maximize data capacity
      QRCode.toCanvas(qrCanvasRef.current, generatedKey, {
        width: 320,
        margin: 2,
        errorCorrectionLevel: 'L',
        color: {
          dark: '#4f46e5', // Indigo-600
          light: '#ffffff'
        }
      }, (error) => {
        if (error) {
          console.error("QR Code generation error", error);
          setQrError("This quiz is too large to be shared via QR code. Please use the Text Key instead.");
        }
      });
    }
  }, [generatedKey]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setSessionQuiz(null);
  };

  const performImport = async (key: string) => {
    if (!key.trim()) return;
    setIsImporting(true);
    const decoded = await decodeQuizKey(key.trim());
    setIsImporting(false);

    if (decoded) {
      if (quizzes.some(q => q.id === decoded.id)) {
        alert("This quiz is already in your library.");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        alert(`Successfully imported: ${decoded.title}`);
        return true;
      }
    } else {
      alert("Invalid share key or QR code. The data might be corrupted.");
    }
    return false;
  };

  const handleImport = () => performImport(importKey);

  const onQRScanSuccess = async (decodedText: string) => {
    setIsScanning(false);
    await performImport(decodedText);
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this quiz?")) {
      setQuizzes(quizzes.filter(q => q.id !== id));
    }
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const startQuizSession = (quiz: QuizSet, shuffle: boolean) => {
    const quizToRun = shuffle 
      ? { ...quiz, questions: shuffleArray(quiz.questions) } 
      : { ...quiz };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowStartPrompt(null);
  };

  const startRandomQuizSession = (quiz: QuizSet, count: number) => {
    const total = quiz.questions.length;
    const n = Math.max(1, Math.min(count, total));
    const shuffled = shuffleArray(quiz.questions);
    const selected = shuffled.slice(0, n);

    const quizToRun = { 
      ...quiz, 
      title: `${quiz.title} (Random ${n})`,
      questions: selected 
    };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowRandomPrompt(null);
  };

  const renderHome = () => (
    <div className="space-y-12">
      {/* Header Section */}
      <section className="text-center py-12 px-6 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl text-white shadow-xl shadow-indigo-100">
        <h1 className="text-4xl md:text-5xl font-extrabold mb-4">Master Your Knowledge</h1>
        <p className="text-indigo-100 text-lg mb-8 max-w-2xl mx-auto">Create custom self-test sets, import community shared tests, and track your progress with professional auto-grading.</p>

        <div className="flex flex-col items-center gap-6">
          <div className="flex flex-col sm:flex-row justify-center gap-4 w-full max-w-2xl">
            <Button size="lg" variant="success" className="shadow-lg px-8" onClick={() => setCurrentView('CREATE')}>Create New Quiz</Button>

            <div className="flex-grow flex border border-white/20 rounded-xl overflow-hidden bg-white/10 backdrop-blur-sm p-1">
              <input 
                type="text" 
                placeholder="Paste Share Key..." 
                className="bg-transparent px-4 py-2 outline-none text-white placeholder-indigo-200 w-full"
                value={importKey}
                onChange={(e) => setImportKey(e.target.value)}
              />
              <Button variant="secondary" className="rounded-lg mr-1" onClick={handleImport} isLoading={isImporting}>Import</Button>
              <Button 
                variant="ghost" 
                className="bg-white/20 text-white hover:bg-white/30 rounded-lg p-2" 
                title="Scan QR Code"
                onClick={() => setIsScanning(true)}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
              </Button>
            </div>
          </div>
          <p className="text-xs text-indigo-200">Tip: Click the QR icon to import via camera scanning</p>
        </div>
      </section>

      {/* Library Section */}
      <section>
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-bold text-slate-800">My Library</h2>
          <span className="text-slate-400 text-sm font-medium">{quizzes.length} Quizzes Saved</span>
        </div>

        {quizzes.length === 0 ? (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <div className="mb-4 text-slate-300">
              <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.246.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            </div>
            <p className="text-slate-400 text-lg">Your library is empty. Create your first quiz above!</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { 
                  const q = quizzes.find(item => item.id === id);
                  if (q) setShowStartPrompt(q);
                }}
                onRandomStart={(id) => {
                  const q = quizzes.find(item => item.id === id);
                  if (q) {
                    setShowRandomPrompt(q);
                    setRandomN(Math.min(5, q.questions.length));
                  }
                }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>

      {/* QR Scanner */}
      {isScanning && (
        <QRScanner onScanSuccess={onQRScanSuccess} onClose={() => setIsScanning(false)} />
      )}

      {/* Dev Docs */}
      {showDevDocs && (
        <DevDocs onClose={() => setShowDevDocs(false)} />
      )}

      {/* Start Quiz Prompt Modal */}
      {showStartPrompt && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-md w-full shadow-2xl animate-in fade-in zoom-in duration-300">
            <h3 className="text-xl font-bold text-slate-800 mb-2">Ready to start?</h3>
            <p className="text-slate-500 text-sm mb-6">Would you like to shuffle the questions for this test session?</p>

            <div className="space-y-3">
              <Button 
                variant="primary" 
                className="w-full py-3 text-lg" 
                onClick={() => startQuizSession(showStartPrompt, true)}
              >
                Yes, Shuffle Questions
              </Button>
              <Button 
                variant="secondary" 
                className="w-full py-3" 
                onClick={() => startQuizSession(showStartPrompt, false)}
              >
                No, Use Original Order
              </Button>
              <Button 
                variant="ghost" 
                className="w-full" 
                onClick={() => setShowStartPrompt(null)}
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Random N Modal */}
      {showRandomPrompt && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-w-sm w-full shadow-2xl animate-in fade-in zoom-in duration-300">
            <h3 className="text-xl font-bold text-slate-800 mb-2">Randomly Extract Questions</h3>
            <p className="text-slate-500 text-sm mb-6">Enter how many questions you want to extract from the total {showRandomPrompt.questions.length}.</p>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Number of Questions (N)</label>
                <input 
                  type="number" 
                  min="1" 
                  max={showRandomPrompt.questions.length}
                  className="w-full p-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-center text-2xl font-bold text-indigo-600"
                  value={randomN}
                  onChange={(e) => setRandomN(parseInt(e.target.value) || 0)}
                />
              </div>

              <div className="space-y-2">
                <Button 
                  variant="primary" 
                  className="w-full py-3" 
                  onClick={() => startRandomQuizSession(showRandomPrompt, randomN)}
                  disabled={randomN < 1 || randomN > showRandomPrompt.questions.length}
                >
                  Start Random Test
                </Button>
                <Button 
                  variant="ghost" 
                  className="w-full" 
                  onClick={() => setShowRandomPrompt(null)}
                >
                  Cancel
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-8 max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
            <h3 className="text-xl font-bold text-slate-800 mb-2 text-center">Share This Quiz</h3>
            <p className="text-slate-500 text-sm mb-6 text-center">Others can scan this code or use the text key to import.</p>

            <div className="flex flex-col items-center justify-center mb-6 min-h-[300px]">
              {qrError ? (
                <div className="p-6 bg-red-50 border border-red-200 rounded-2xl text-red-700 text-center max-w-xs">
                  <svg className="w-12 h-12 mx-auto mb-3 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  <p className="text-sm font-medium">{qrError}</p>
                </div>
              ) : (
                <div className="p-2 bg-white border-4 border-indigo-50 rounded-2xl">
                  <canvas ref={qrCanvasRef} className="w-full max-w-[320px] h-auto aspect-square"></canvas>
                  {!generatedKey && (
                    <div className="absolute inset-0 flex items-center justify-center bg-white/80 rounded-2xl">
                       <svg className="animate-spin h-8 w-8 text-indigo-600" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-6 relative group">
              {generatedKey ? (
                <>
                  <textarea 
                    readOnly 
                    className="w-full bg-transparent text-[10px] font-mono break-all focus:outline-none h-20 resize-none"
                    value={generatedKey}
                  />
                  <div className="absolute inset-0 bg-slate-900/5 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
                    <span className="bg-white px-2 py-1 rounded text-xs font-bold text-indigo-600 shadow-sm">Text Key</span>
                  </div>
                </>
              ) : (
                <div className="h-20 flex items-center justify-center text-slate-400">
                  <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Preparing data...
                </div>
              )}
            </div>

            <div className="flex gap-4">
              <Button 
                variant="primary" 
                className="flex-grow" 
                disabled={!generatedKey}
                onClick={() => {
                  navigator.clipboard.writeText(generatedKey);
                  alert("Key copied to clipboard!");
                }}
              >
                Copy Text Key
              </Button>
              <Button variant="ghost" onClick={() => setShowShareModal(null)}>Close</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50">
      <nav className="bg-white border-b border-slate-200 h-16 sticky top-0 z-30 flex items-center px-6">
        <div className="max-w-7xl mx-auto w-full flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('HOME')}>
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
            </div>
            <span className="font-bold text-xl tracking-tight text-slate-800">Quiz<span className="text-indigo-600">Genius</span></span>
          </div>
          {currentView !== 'HOME' && (
             <Button variant="ghost" size="sm" onClick={() => setCurrentView('HOME')}>Back to Home</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {currentView === 'HOME' && renderHome()}
        {currentView === 'CREATE' && (
          <QuizEditor 
            onSave={handleSaveQuiz} 
            onCancel={() => setCurrentView('HOME')} 
          />
        )}
        {currentView === 'QUIZ' && sessionQuiz && (
          <QuizTaker 
            quiz={sessionQuiz} 
            onExit={() => { setCurrentView('HOME'); setSessionQuiz(null); }} 
          />
        )}
      </main>

      <footer className="py-10 text-center border-t border-slate-200 bg-white">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-slate-400 text-sm">&copy; 2024 QuizGenius. Built for lifelong learners.</p>
          <div className="flex gap-6">
            <button 
              className="text-indigo-600 hover:text-indigo-700 text-sm font-semibold transition-colors"
              onClick={() => setShowDevDocs(true)}
            >
              出题人指南 / Developer Docs
            </button>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-slate-400 hover:text-slate-600 text-sm">Gemini Billing Info</a>
          </div>
        </div>
      </footer>
    </div>
  );
}

import React from 'react';
import { Button } from './Button';

export type DialogType = 'success' | 'error' | 'info' | 'warning' | 'confirm';

interface DialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm?: () => void;
  title: string;
  message: string;
  type?: DialogType;
  confirmText?: string;
  cancelText?: string;
}

export const Dialog: React.FC<DialogProps> = ({
  isOpen,
  onClose,
  onConfirm,
  title,
  message,
  type = 'info',
  confirmText = 'Confirm',
  cancelText = 'Cancel'
}) => {
  if (!isOpen) return null;

  const icons = {
    success: (
      <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-4">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
      </div>
    ),
    error: (
      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-4">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
      </div>
    ),
    warning: (
      <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mb-4">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
      </div>
    ),
    info: (
      <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mb-4">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
      </div>
    ),
    confirm: (
      <div className="w-12 h-12 bg-slate-100 text-slate-600 rounded-full flex items-center justify-center mb-4">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
      </div>
    )
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200 flex flex-col items-center text-center">
        {icons[type]}
        <h3 className="text-xl font-bold text-slate-800 mb-2">{title}</h3>
        <p className="text-slate-500 mb-8 whitespace-pre-wrap">{message}</p>

        <div className="flex gap-3 w-full">
          {type === 'confirm' ? (
            <>
              <Button variant="ghost" className="flex-1" onClick={onClose}>{cancelText}</Button>
              <Button variant="danger" className="flex-1" onClick={() => { onConfirm?.(); onClose(); }}>{confirmText}</Button>
            </>
          ) : (
            <Button variant="primary" className="w-full py-3" onClick={onClose}>Got it</Button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import QRCode from 'qrcode';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { QRScanner } from './components/QRScanner';
import { DevDocs } from './components/DevDocs';
import { Dialog, DialogType } from './components/Dialog';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';

export default function App() {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [sessionQuiz, setSessionQuiz] = useState<QuizSet | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);
  const [showStartPrompt, setShowStartPrompt] = useState<QuizSet | null>(null);
  const [showRandomPrompt, setShowRandomPrompt] = useState<QuizSet | null>(null);
  const [randomN, setRandomN] = useState<number>(5);
  const [showDevDocs, setShowDevDocs] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string>('');
  const [qrError, setQrError] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  // Dialog State
  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    type: DialogType;
    onConfirm?: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    type: 'info'
  });

  const showAlert = (title: string, message: string, type: DialogType = 'info') => {
    setDialog({ isOpen: true, title, message, type });
  };

  const showConfirm = (title: string, message: string, onConfirm: () => void) => {
    setDialog({ isOpen: true, title, message, type: 'confirm', onConfirm });
  };

  const qrCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  useEffect(() => {
    if (showShareModal) {
      const quiz = quizzes.find(q => q.id === showShareModal);
      if (quiz) {
        setQrError(null);
        encodeQuizKey(quiz).then(key => {
          setGeneratedKey(key);
        });
      }
    } else {
      setGeneratedKey('');
      setQrError(null);
    }
  }, [showShareModal, quizzes]);

  useEffect(() => {
    if (generatedKey && qrCanvasRef.current) {
      QRCode.toCanvas(qrCanvasRef.current, generatedKey, {
        width: 320,
        margin: 2,
        errorCorrectionLevel: 'L',
        color: {
          dark: '#4f46e5',
          light: '#ffffff'
        }
      }, (error) => {
        if (error) {
          console.error("QR Code generation error", error);
          setQrError("This quiz is too large for QR. Use the Text Key.");
        }
      });
    }
  }, [generatedKey]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setSessionQuiz(null);
  };

  const performImport = async (key: string) => {
    if (!key.trim()) return;
    setIsImporting(true);
    const decoded = await decodeQuizKey(key.trim());
    setIsImporting(false);

    if (decoded) {
      if (quizzes.some(q => q.id === decoded.id)) {
        showAlert("Duplicate Quiz", "This quiz is already in your library.", "warning");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        showAlert("Success", `Successfully imported: ${decoded.title}`, "success");
        return true;
      }
    } else {
      showAlert("Import Failed", "Invalid share key or QR code. The data might be corrupted.", "error");
    }
    return false;
  };

  const handleImport = () => performImport(importKey);

  const onQRScanSuccess = async (decodedText: string) => {
    setIsScanning(false);
    await performImport(decodedText);
  };

  const handleDelete = (id: string) => {
    showConfirm("Delete Quiz", "Are you sure you want to delete this quiz set permanently?", () => {
      setQuizzes(quizzes.filter(q => q.id !== id));
    });
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const startQuizSession = (quiz: QuizSet, shuffle: boolean) => {
    const quizToRun = shuffle 
      ? { ...quiz, questions: shuffleArray(quiz.questions) } 
      : { ...quiz };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowStartPrompt(null);
  };

  const startRandomQuizSession = (quiz: QuizSet, count: number) => {
    const total = quiz.questions.length;
    const n = Math.max(1, Math.min(count, total));
    const shuffled = shuffleArray(quiz.questions);
    const selected = shuffled.slice(0, n);

    const quizToRun = { 
      ...quiz, 
      title: `${quiz.title} (Random ${n})`,
      questions: selected 
    };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowRandomPrompt(null);
  };

  const renderHome = () => (
    <div className="space-y-12">
      <section className="text-center py-12 px-6 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl text-white shadow-xl">
        <h1 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">Master Your Knowledge</h1>
        <p className="text-indigo-100 text-lg mb-8 max-w-2xl mx-auto">Create custom self-test sets, import community tests, and track your progress with professional auto-grading.</p>

        <div className="flex flex-col items-center gap-6">
          <div className="flex flex-col sm:flex-row justify-center gap-4 w-full max-w-2xl">
            <Button size="lg" variant="success" className="shadow-lg px-8" onClick={() => setCurrentView('CREATE')}>Create New Quiz</Button>

            <div className="flex-grow flex border border-white/20 rounded-xl overflow-hidden bg-white/10 backdrop-blur-sm p-1">
              <input 
                type="text" 
                placeholder="Paste Share Key..." 
                className="bg-transparent px-4 py-2 outline-none text-white placeholder-indigo-200 w-full"
                value={importKey}
                onChange={(e) => setImportKey(e.target.value)}
              />
              <Button variant="secondary" className="rounded-lg mr-1" onClick={handleImport} isLoading={isImporting}>Import</Button>
              <Button 
                variant="ghost" 
                className="bg-white/20 text-white hover:bg-white/30 rounded-lg p-2" 
                title="Scan QR Code"
                onClick={() => setIsScanning(true)}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
              </Button>
            </div>
          </div>
        </div>
      </section>

      <section>
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-bold text-slate-800">My Library</h2>
          <span className="text-slate-400 text-sm font-medium">{quizzes.length} Quizzes Saved</span>
        </div>

        {quizzes.length === 0 ? (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <div className="mb-4 text-slate-300">
              <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.246.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            </div>
            <p className="text-slate-400 text-lg">Your library is empty. Create your first quiz above!</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { 
                  const q = quizzes.find(item => item.id === id);
                  if (q) setShowStartPrompt(q);
                }}
                onRandomStart={(id) => {
                  const q = quizzes.find(item => item.id === id);
                  if (q) {
                    setShowRandomPrompt(q);
                    setRandomN(Math.min(5, q.questions.length));
                  }
                }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>

      {isScanning && <QRScanner onScanSuccess={onQRScanSuccess} onClose={() => setIsScanning(false)} />}
      {showDevDocs && <DevDocs onClose={() => setShowDevDocs(false)} />}

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
            <h3 className="text-xl font-bold text-slate-800 mb-2 text-center">Share This Quiz</h3>
            <p className="text-slate-500 text-sm mb-6 text-center">Scan QR or use text key to import.</p>
            <div className="flex flex-col items-center mb-6">
              <canvas ref={qrCanvasRef} className="max-w-full h-auto aspect-square rounded-xl bg-indigo-50/50 p-2"></canvas>
            </div>
            <div className="bg-slate-50 p-4 rounded-xl border mb-6 relative group overflow-hidden">
               <textarea readOnly className="w-full bg-transparent text-[10px] font-mono h-20 outline-none" value={generatedKey} />
            </div>
            <div className="flex gap-4">
              <Button className="flex-grow" onClick={() => {
                navigator.clipboard.writeText(generatedKey);
                showAlert("Copied", "Key copied to clipboard!", "success");
              }}>Copy Key</Button>
              <Button variant="ghost" onClick={() => setShowShareModal(null)}>Close</Button>
            </div>
          </div>
        </div>
      )}

      {/* Random Selection Prompt */}
      {showRandomPrompt && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95">
            <h3 className="text-xl font-bold text-slate-800 mb-2">Random Extract</h3>
            <p className="text-slate-500 text-sm mb-6">Select number of questions from {showRandomPrompt.questions.length}.</p>
            <input 
              type="number" min="1" max={showRandomPrompt.questions.length}
              className="w-full p-4 rounded-xl border text-center text-3xl font-bold text-indigo-600 mb-6 focus:ring-2 focus:ring-indigo-500 outline-none"
              value={randomN}
              onChange={(e) => setRandomN(parseInt(e.target.value) || 1)}
            />
            <div className="flex flex-col gap-2">
              <Button onClick={() => startRandomQuizSession(showRandomPrompt, randomN)}>Start Test</Button>
              <Button variant="ghost" onClick={() => setShowRandomPrompt(null)}>Cancel</Button>
            </div>
          </div>
        </div>
      )}

      {/* Global Dialog */}
      <Dialog 
        isOpen={dialog.isOpen}
        onClose={() => setDialog(prev => ({ ...prev, isOpen: false }))}
        onConfirm={dialog.onConfirm}
        title={dialog.title}
        message={dialog.message}
        type={dialog.type}
      />
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50">
      <nav className="bg-white border-b border-slate-200 h-16 sticky top-0 z-30 flex items-center px-6">
        <div className="max-w-7xl mx-auto w-full flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('HOME')}>
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-200">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
            </div>
            <span className="font-bold text-xl tracking-tight text-slate-800">Quiz<span className="text-indigo-600">Genius</span></span>
          </div>
          {currentView !== 'HOME' && <Button variant="ghost" size="sm" onClick={() => setCurrentView('HOME')}>Exit Editor</Button>}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {currentView === 'HOME' && renderHome()}
        {currentView === 'CREATE' && <QuizEditor onSave={handleSaveQuiz} onCancel={() => setCurrentView('HOME')} />}
        {currentView === 'QUIZ' && sessionQuiz && <QuizTaker quiz={sessionQuiz} onExit={() => { setCurrentView('HOME'); setSessionQuiz(null); }} />}
      </main>

      <footer className="py-10 border-t border-slate-200 bg-white">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-slate-400 text-sm">&copy; 2024 QuizGenius.</p>
          <div className="flex gap-6">
            <button className="text-indigo-600 hover:underline text-sm font-semibold" onClick={() => setShowDevDocs(true)}>出题人指南</button>
          </div>
        </div>
      </footer>
    </div>
  );
}

import React, { useState } from 'react';
import { QuizSet, Question, QuestionType } from '../types';
import { Button } from './Button';
import { JSONImporter } from './JSONImporter';
import { Dialog } from './Dialog';

interface QuizEditorProps {
  onSave: (quiz: QuizSet) => void;
  onCancel: () => void;
  initialQuiz?: QuizSet;
}

export const QuizEditor: React.FC<QuizEditorProps> = ({ onSave, onCancel, initialQuiz }) => {
  const [title, setTitle] = useState(initialQuiz?.title || '');
  const [description, setDescription] = useState(initialQuiz?.description || '');
  const [questions, setQuestions] = useState<Question[]>(initialQuiz?.questions || []);
  const [isJsonOpen, setIsJsonOpen] = useState(false);
  const [alert, setAlert] = useState<{ isOpen: boolean; title: string; message: string }>({
    isOpen: false,
    title: '',
    message: ''
  });

  const addQuestion = (type: QuestionType) => {
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      text: '',
      points: 5,
      correctAnswers: [],
      options: (type === QuestionType.SINGLE_CHOICE || type === QuestionType.MULTIPLE_CHOICE) 
        ? [{ id: '1', text: 'Option 1' }, { id: '2', text: 'Option 2' }] 
        : undefined,
    };
    setQuestions([...questions, newQuestion]);
  };

  const handleSave = () => {
    if (!title.trim()) {
      setAlert({ isOpen: true, title: "Title Required", message: "Please provide a title for your quiz set before saving." });
      return;
    }
    if (questions.length === 0) {
      setAlert({ isOpen: true, title: "No Questions", message: "A quiz set must have at least one question." });
      return;
    }
    onSave({
      id: initialQuiz?.id || Math.random().toString(36).substr(2, 9),
      title,
      description,
      createdAt: Date.now(),
      questions,
    });
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32 animate-in slide-in-from-bottom-8 duration-500">
      {isJsonOpen && <JSONImporter onImport={(d) => {
        if (d.title) setTitle(d.title);
        if (d.description) setDescription(d.description);
        if (d.questions) setQuestions(d.questions as Question[]);
      }} onClose={() => setIsJsonOpen(false)} />}

      <Dialog 
        isOpen={alert.isOpen} 
        onClose={() => setAlert(prev => ({ ...prev, isOpen: false }))}
        title={alert.title}
        message={alert.message}
        type="warning"
      />

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">{initialQuiz ? 'Edit Quiz' : 'Create New Quiz'}</h1>
        <Button variant="secondary" size="sm" onClick={() => setIsJsonOpen(true)}>Import JSON</Button>
      </div>

      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h2 className="text-lg font-bold text-slate-800 mb-6">General Information</h2>
        <div className="space-y-4">
          <input 
            type="text" className="w-full p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-xl font-bold"
            value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Quiz Title"
          />
          <textarea 
            className="w-full p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
            rows={2} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Describe what learners will test..."
          />
        </div>
      </section>

      <section className="space-y-6">
        <div className="flex justify-between items-center border-b pb-4">
          <h2 className="text-lg font-bold text-slate-800">Questions ({questions.length})</h2>
          <div className="flex gap-2 flex-wrap">
            {Object.values(QuestionType).map(type => (
              <Button key={type} size="sm" variant="secondary" onClick={() => addQuestion(type)}>+ {type.toLowerCase().replace('_', ' ')}</Button>
            ))}
          </div>
        </div>

        {questions.map((q, idx) => (
          <div key={q.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 group relative">
             <button onClick={() => setQuestions(questions.filter(item => item.id !== q.id))} className="absolute top-4 right-4 text-slate-300 hover:text-red-500">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
             </button>
             <div className="flex items-center gap-2 mb-4">
               <span className="w-6 h-6 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center text-xs font-bold">{idx + 1}</span>
               <span className="text-xs font-bold uppercase tracking-widest text-indigo-500">{q.type}</span>
             </div>
             <textarea 
               className="w-full p-4 bg-slate-50 rounded-xl border-none font-medium mb-4 focus:bg-white focus:ring-2 focus:ring-indigo-500 transition-all"
               value={q.text} onChange={(e) => updateQuestion(q.id, { text: e.target.value })} placeholder="Question text..."
             />
             {/* Question Logic UI (Condensed for brevity) */}
             <div className="flex items-center gap-2">
               <span className="text-xs font-bold text-slate-400">POINTS:</span>
               <input type="number" className="w-16 p-2 border rounded-lg text-center font-bold" value={q.points} onChange={(e) => updateQuestion(q.id, { points: parseInt(e.target.value) || 0 })} />
             </div>
          </div>
        ))}
      </section>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-md border-t flex justify-center gap-4 z-40">
        <Button variant="ghost" onClick={onCancel}>Cancel</Button>
        <Button variant="primary" className="px-12 shadow-xl shadow-indigo-200" onClick={handleSave}>Save Quiz</Button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, UserAnswers, QuestionType, GradeResult } from '../types';
import { Button } from './Button';
import { QuestionRenderer } from './QuestionRenderer';
import { Dialog } from './Dialog';

interface QuizTakerProps {
  quiz: QuizSet;
  onExit: () => void;
}

export const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, onExit }) => {
  const [answers, setAnswers] = useState<UserAnswers>({});
  const [confusedIds, setConfusedIds] = useState<Set<string>>(new Set());
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [grades, setGrades] = useState<GradeResult[]>([]);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const handleAnswerChange = (qId: string, value: string | string[]) => {
    setAnswers(prev => ({ ...prev, [qId]: value }));
  };

  const toggleConfusion = (qId: string) => {
    setConfusedIds(prev => {
      const next = new Set(prev);
      if (next.has(qId)) next.delete(qId);
      else next.add(qId);
      return next;
    });
  };

  const calculateGrade = () => {
    const results: GradeResult[] = quiz.questions.map(q => {
      const userAns = answers[q.id];
      let isCorrect = false;
      let score = 0;
      switch (q.type) {
        case QuestionType.SINGLE_CHOICE:
        case QuestionType.TRUE_FALSE:
          isCorrect = userAns === q.correctAnswers[0];
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.MULTIPLE_CHOICE:
          const sortedCorrect = [...q.correctAnswers].sort().join(',');
          const sortedUser = Array.isArray(userAns) ? [...userAns].sort().join(',') : '';
          isCorrect = sortedCorrect === sortedUser;
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.FILL_IN_THE_BLANK:
          const normalizedUser = (userAns as string || '').trim().toLowerCase();
          isCorrect = q.correctAnswers.some(ans => ans.trim().toLowerCase() === normalizedUser);
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.SUBJECTIVE:
          isCorrect = true; score = 0;
          break;
      }
      return { questionId: q.id, isCorrect, score, maxScore: q.points };
    });
    setGrades(results);
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const answeredCount = quiz.questions.filter(q => {
    const val = answers[q.id];
    return val !== undefined && (Array.isArray(val) ? val.length > 0 : val.trim().length > 0);
  }).length;

  const totalScore = grades.reduce((acc, g) => acc + g.score, 0);
  const maxScore = quiz.questions.reduce((acc, q) => q.type !== QuestionType.SUBJECTIVE ? acc + q.points : acc, 0);

  return (
    <div className="relative max-w-7xl mx-auto px-4 pb-20 flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      <Dialog 
        isOpen={showExitConfirm}
        onClose={() => setShowExitConfirm(false)}
        onConfirm={onExit}
        type="confirm"
        title="Exit Quiz?"
        message="Your progress will not be saved. Are you sure you want to end this session?"
        confirmText="Exit Session"
      />

      <div className="w-full lg:max-w-4xl space-y-8">
        <div className="mb-8">
          <h1 className="text-3xl font-extrabold text-slate-800 mb-2">{isSubmitted ? 'Test Report: ' : ''}{quiz.title}</h1>
          <p className="text-slate-500">{quiz.description}</p>
        </div>

        <div className="space-y-12">
          {quiz.questions.map((q, idx) => {
            const grade = grades.find(g => g.questionId === q.id);
            return (
              <div key={q.id} id={`q-container-${q.id}`} className="space-y-4">
                <QuestionRenderer
                  question={q} index={idx}
                  answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE ? [] : '')}
                  onChange={(val) => handleAnswerChange(q.id, val)}
                  isGraded={isSubmitted}
                  isConfused={confusedIds.has(q.id)}
                  onToggleConfusion={() => toggleConfusion(q.id)}
                />
                {isSubmitted && (
                  <div className={`p-6 rounded-2xl border ${grade?.isCorrect || q.type === QuestionType.SUBJECTIVE ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
                    <div className="flex justify-between items-center mb-4">
                       <span className="font-bold">{q.type === QuestionType.SUBJECTIVE ? 'Subjective Check' : (grade?.isCorrect ? '✓ CORRECT' : '✗ INCORRECT')}</span>
                       <span className="text-sm font-bold">Score: {grade?.score} / {grade?.maxScore}</span>
                    </div>
                    {q.type !== QuestionType.SUBJECTIVE ? (
                      <div className="text-sm opacity-80">Correct Answer: {q.correctAnswers.join(' / ')}</div>
                    ) : (
                      <div className="text-sm">Reference: {q.subjectiveReference}</div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <aside className="w-full lg:w-72 lg:sticky lg:top-24 z-30 order-first lg:order-last">
        <div className="bg-white rounded-2xl border p-6 shadow-xl space-y-6">
          <div>
             <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-2">{isSubmitted ? 'Score' : 'Progress'}</h3>
             <div className="text-2xl font-black text-indigo-600">
               {isSubmitted ? `${totalScore} / ${maxScore}` : `${answeredCount} / ${quiz.questions.length}`}
             </div>
          </div>
          <div className="flex flex-col gap-2">
             {!isSubmitted ? (
               <Button variant="primary" className="w-full py-4" onClick={calculateGrade}>Submit Quiz</Button>
             ) : (
               <Button variant="primary" className="w-full" onClick={onExit}>Finish Review</Button>
             )}
             <Button variant="ghost" onClick={() => setShowExitConfirm(true)}>Exit</Button>
          </div>
        </div>
      </aside>
    </div>
  );
};

