      text: '',
      points: 5,
      correctAnswers: type === QuestionType.FILL_IN_THE_BLANK ? [''] : [],
      options: (type === QuestionType.SINGLE_CHOICE || type === QuestionType.MULTIPLE_CHOICE) 
        ? [{ id: '1', text: 'Option 1' }, { id: '2', text: 'Option 2' }] 
        : undefined,
    };
    setQuestions([...questions, newQuestion]);
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  const handleOptionChange = (qId: string, optId: string, text: string) => {
    const q = questions.find(item => item.id === qId);
    if (!q || !q.options) return;
    const newOptions = q.options.map(o => o.id === optId ? { ...o, text } : o);
    updateQuestion(qId, { options: newOptions });
  };

  const toggleCorrectAnswer = (qId: string, val: string, isSingle: boolean) => {
    const q = questions.find(item => item.id === qId);
    if (!q) return;
    let newAnswers: string[];
    if (isSingle) {
      newAnswers = [val];
    } else {
      newAnswers = q.correctAnswers.includes(val)
        ? q.correctAnswers.filter(a => a !== val)
        : [...q.correctAnswers, val];
    }
    updateQuestion(qId, { correctAnswers: newAnswers });
  };

  const addOption = (qId: string) => {
    const q = questions.find(item => item.id === qId);
    if (!q || !q.options) return;
    const nextId = (q.options.length + 1).toString();
    updateQuestion(qId, { options: [...q.options, { id: nextId, text: `Option ${nextId}` }] });
  };

  const removeOption = (qId: string, optId: string) => {
    const q = questions.find(item => item.id === qId);
    if (!q || !q.options || q.options.length <= 1) return;
    updateQuestion(qId, { 
      options: q.options.filter(o => o.id !== optId),
      correctAnswers: q.correctAnswers.filter(a => a !== optId)
    });
  };

  // Multi-blank handlers
  const addBlank = (qId: string) => {
    const q = questions.find(item => item.id === qId);
    if (!q) return;
    updateQuestion(qId, { correctAnswers: [...q.correctAnswers, ''] });
  };

  const removeBlank = (qId: string, index: number) => {
    const q = questions.find(item => item.id === qId);
    if (!q || q.correctAnswers.length <= 1) return;
    const newAnswers = [...q.correctAnswers];
    newAnswers.splice(index, 1);
    updateQuestion(qId, { correctAnswers: newAnswers });
  };

  const updateBlankValue = (qId: string, index: number, val: string) => {
    const q = questions.find(item => item.id === qId);
    if (!q) return;
    const newAnswers = [...q.correctAnswers];
    newAnswers[index] = val;
    updateQuestion(qId, { correctAnswers: newAnswers });
  };

  const handleSave = () => {
    if (!title.trim()) {
      setAlert({ isOpen: true, title: "Title Required", message: "Please provide a title for your quiz set." });
      return;
    }
    if (questions.length === 0) {
      setAlert({ isOpen: true, title: "No Questions", message: "Add at least one question." });
      return;
    }
    for (let i = 0; i < questions.length; i++) {
      const q = questions[i];
      if (!q.text.trim()) {
        setAlert({ isOpen: true, title: "Empty Question", message: `Question ${i + 1} has no text.` });
        return;
      }
      if (q.type !== QuestionType.SUBJECTIVE && q.correctAnswers.filter(a => a.trim()).length === 0) {
        setAlert({ isOpen: true, title: "No Correct Answer", message: `Question ${i + 1} must have at least one correct answer.` });
        return;
      }
    }

    onSave({
      id: initialQuiz?.id || Math.random().toString(36).substr(2, 9),
      title,
      description,
      createdAt: Date.now(),
      questions,
    });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32 animate-in slide-in-from-bottom-8 duration-500">
      {isJsonOpen && <JSONImporter onImport={(d) => {
        if (d.title) setTitle(d.title);
        if (d.description) setDescription(d.description);
        if (d.questions) setQuestions(d.questions as Question[]);
      }} onClose={() => setIsJsonOpen(false)} />}

      <Dialog 
        isOpen={alert.isOpen} 
        onClose={() => setAlert(prev => ({ ...prev, isOpen: false }))}
        title={alert.title}
        message={alert.message}
        type="warning"
      />

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">{initialQuiz ? 'Edit Quiz' : 'Create New Quiz'}</h1>
        <Button variant="secondary" size="sm" onClick={() => setIsJsonOpen(true)}>Import JSON</Button>
      </div>

      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <div className="space-y-4">
          <input 
            type="text" className="w-full p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-xl font-bold"
            value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Quiz Title (e.g., Biology Midterm)"
          />
          <textarea 
            className="w-full p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
            rows={2} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Brief description of the test content..."
          />
        </div>
      </section>

      <section className="space-y-6">
        <div className="flex justify-between items-center border-b border-slate-200 pb-4">
          <h2 className="text-lg font-bold text-slate-800">Questions ({questions.length})</h2>
          <div className="flex gap-2 flex-wrap">
            {Object.values(QuestionType).map(type => (
              <Button key={type} size="sm" variant="secondary" onClick={() => addQuestion(type)}>
                + {type.toLowerCase().replace(/_/g, ' ')}
              </Button>
            ))}
          </div>
        </div>

        {questions.map((q, idx) => (
          <div key={q.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 group relative animate-in fade-in slide-in-from-top-4">
             <button onClick={() => setQuestions(questions.filter(item => item.id !== q.id))} className="absolute top-4 right-4 text-slate-300 hover:text-red-500 transition-colors">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
             </button>

             <div className="flex items-center gap-2 mb-4">
               <span className="w-6 h-6 bg-indigo-600 text-white rounded-full flex items-center justify-center text-xs font-bold">{idx + 1}</span>
               <span className="text-xs font-bold uppercase tracking-widest text-indigo-500">{q.type.replace(/_/g, ' ')}</span>
             </div>

             <textarea 
               className="w-full p-4 bg-slate-50 rounded-xl border-none font-medium mb-4 focus:bg-white focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
               value={q.text} onChange={(e) => updateQuestion(q.id, { text: e.target.value })} placeholder="Type your question here..."
             />

             <div className="space-y-3 mb-6">
               {(q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE) && (
                 <>
                   {q.options?.map(opt => (
                     <div key={opt.id} className="flex items-center gap-2">
                       <button 
                         onClick={() => toggleCorrectAnswer(q.id, opt.id, q.type === QuestionType.SINGLE_CHOICE)}
                         className={`w-6 h-6 rounded flex items-center justify-center border transition-all ${q.correctAnswers.includes(opt.id) ? 'bg-emerald-500 border-emerald-600 text-white' : 'bg-white border-slate-200 text-transparent'}`}
                       >
                         <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
                       </button>
                       <input 
                         type="text" className="flex-grow p-2 text-sm bg-slate-50 border-none rounded-lg focus:bg-white focus:ring-1 focus:ring-indigo-300 outline-none"
                         value={opt.text} onChange={(e) => handleOptionChange(q.id, opt.id, e.target.value)}
                       />
                       <button onClick={() => removeOption(q.id, opt.id)} className="text-slate-300 hover:text-red-400">
                         <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                       </button>
                     </div>
                   ))}
                   <Button variant="ghost" size="sm" onClick={() => addOption(q.id)} className="text-indigo-600">+ Add Option</Button>
                 </>
               )}

               {q.type === QuestionType.TRUE_FALSE && (
                 <div className="flex gap-2">
                   {['true', 'false'].map(val => (
                     <button
                        key={val}
                        onClick={() => updateQuestion(q.id, { correctAnswers: [val] })}
                        className={`flex-1 py-2 rounded-lg border font-bold capitalize transition-all ${q.correctAnswers[0] === val ? 'bg-indigo-600 border-indigo-700 text-white' : 'bg-white border-slate-200 text-slate-500'}`}
                     >
                       {val}
                     </button>
                   ))}
                 </div>
               )}

               {q.type === QuestionType.FILL_IN_THE_BLANK && (
                 <div className="space-y-4">
                   <label className="block text-[10px] font-bold text-slate-400 uppercase">Blanks & Acceptable Answers (Use | for synonyms)</label>
                   {q.correctAnswers.map((ans, bIdx) => (
                     <div key={bIdx} className="flex items-center gap-2 group/blank animate-in fade-in zoom-in-95">
                       <span className="text-xs font-bold text-slate-400 w-4">{bIdx + 1}.</span>
                       <input 
                         type="text" className="flex-grow p-3 bg-slate-50 rounded-lg border-none focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
                         placeholder="e.g. Paris | paris"
                         value={ans}
                         onChange={(e) => updateBlankValue(q.id, bIdx, e.target.value)}
                       />
                       <button 
                         onClick={() => removeBlank(q.id, bIdx)} 
                         disabled={q.correctAnswers.length <= 1}
                         className="text-slate-300 hover:text-red-400 disabled:opacity-0 transition-opacity"
                       >
                         <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                       </button>
                     </div>
                   ))}
                   <Button variant="ghost" size="sm" onClick={() => addBlank(q.id)} className="text-indigo-600">+ Add Blank</Button>
                 </div>
               )}

               {q.type === QuestionType.SUBJECTIVE && (
                 <div>
                   <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Reference Answer (For review)</label>
                   <textarea 
                     className="w-full p-3 bg-slate-50 rounded-lg border-none focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
                     placeholder="Points to look for in the answer..."
                     value={q.subjectiveReference || ''}
                     onChange={(e) => updateQuestion(q.id, { subjectiveReference: e.target.value })}
                   />
                 </div>
               )}
             </div>

             <div className="flex items-center gap-4 text-xs font-bold text-slate-400 border-t pt-4">
               <div className="flex items-center gap-2">
                 <span>POINTS:</span>
                 <input 
                  type="number" className="w-14 p-1 border rounded text-center text-slate-800" 
                  value={q.points} onChange={(e) => updateQuestion(q.id, { points: parseInt(e.target.value) || 0 })} 
                 />
               </div>
             </div>
          </div>
        ))}
      </section>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-md border-t flex justify-center gap-4 z-40">
        <Button variant="ghost" onClick={onCancel}>Discard Changes</Button>
        <Button variant="primary" className="px-12 shadow-xl shadow-indigo-200" onClick={handleSave}>Save Quiz Set</Button>
      </div>
    </div>
  );
};

import React from 'react';
import { Question, QuestionType } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: string | string[];
  onChange: (value: string | string[]) => void;
  isGraded?: boolean;
  isConfused?: boolean;
  onToggleConfusion?: () => void;
}

export const QuestionRenderer: React.FC<QuestionRendererProps> = ({
  question,
  index,
  answer,
  onChange,
  isGraded = false,
  isConfused = false,
  onToggleConfusion
}) => {
  const handleSingleChoice = (optionId: string) => {
    if (isGraded) return;
    onChange(optionId);
  };

  const handleMultipleChoice = (optionId: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) ? answer : [];
    if (currentAnswers.includes(optionId)) {
      onChange(currentAnswers.filter(id => id !== optionId));
    } else {
      onChange([...currentAnswers, optionId]);
    }
  };

  const handleTrueFalse = (val: string) => {
    if (isGraded) return;
    onChange(val);
  };

  const handleBlankChange = (blankIdx: number, val: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) 
      ? [...answer] 
      : new Array(question.correctAnswers.length).fill('');
    currentAnswers[blankIdx] = val;
    onChange(currentAnswers);
  };

  return (
    <div className={`p-6 rounded-xl bg-white border relative transition-all ${
      isGraded ? 'border-slate-200' : 'border-indigo-100 shadow-sm'
    } ${isConfused && !isGraded ? 'ring-2 ring-yellow-400 border-yellow-400' : ''}`}>

      {/* Confusion Toggle */}
      {!isGraded && onToggleConfusion && (
        <button
          onClick={(e) => {
            e.preventDefault();
            onToggleConfusion();
          }}
          title="Mark as confused / 标记为困惑"
          className={`absolute top-4 right-4 w-8 h-8 rounded-full flex items-center justify-center transition-all border ${
            isConfused 
              ? 'bg-yellow-400 text-white border-yellow-500 shadow-md scale-110' 
              : 'bg-white text-slate-300 border-slate-200 hover:text-yellow-500 hover:border-yellow-300'
          }`}
        >
          <span className="font-bold text-lg">?</span>
        </button>
      )}

      {/* Confused Indicator in Graded view */}
      {isGraded && isConfused && (
        <div className="absolute top-4 right-4 px-2 py-1 bg-yellow-100 text-yellow-700 text-[10px] font-bold rounded uppercase tracking-wider flex items-center gap-1">
          <span className="text-sm">?</span> Marked Confused
        </div>
      )}

      <div className="flex items-start gap-4 mb-4">
        <span className="flex-shrink-0 w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold text-sm">
          {index + 1}
        </span>
        <div className="flex-grow pr-8">
          <div className="flex items-center gap-2 mb-1">
             <span className="text-xs font-bold uppercase tracking-wider text-slate-400">
               {question.type.replace(/_/g, ' ')}
             </span>
             <span className="text-xs text-slate-400">• {question.points} pts</span>
          </div>
          <h4 className="text-lg font-medium text-slate-800 whitespace-pre-wrap">{question.text}</h4>
        </div>
      </div>

      <div className="ml-12 space-y-3">
        {question.type === QuestionType.SINGLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              answer === opt.id 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="radio" 
              name={`q-${question.id}`} 
              checked={answer === opt.id}
              onChange={() => handleSingleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.MULTIPLE_CHOICE && question.options?.map(opt => (
          <label 
            key={opt.id} 
            className={`flex items-center p-3 rounded-lg border cursor-pointer transition-colors ${
              Array.isArray(answer) && answer.includes(opt.id) 
                ? 'border-indigo-600 bg-indigo-50' 
                : 'border-slate-200 hover:border-indigo-300'
            } ${isGraded ? 'pointer-events-none' : ''}`}
          >
            <input 
              type="checkbox" 
              checked={Array.isArray(answer) && answer.includes(opt.id)}
              onChange={() => handleMultipleChoice(opt.id)}
              className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500 border-slate-300"
            />
            <span className="ml-3 text-slate-700">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.TRUE_FALSE && (
          <div className="flex gap-4">
            {['true', 'false'].map(val => (
              <button
                key={val}
                onClick={() => handleTrueFalse(val)}
                className={`flex-1 py-3 px-4 rounded-lg border font-medium capitalize transition-all ${
                  answer === val 
                    ? 'border-indigo-600 bg-indigo-600 text-white shadow-md' 
                    : 'border-slate-200 text-slate-600 hover:bg-slate-50'
                } ${isGraded ? 'pointer-events-none' : ''}`}
              >
                {val}
              </button>
            ))}
          </div>
        )}

        {question.type === QuestionType.FILL_IN_THE_BLANK && (
          <div className="space-y-3">
            {question.correctAnswers.map((_, bIdx) => {
              const currentVal = Array.isArray(answer) ? (answer[bIdx] || '') : (bIdx === 0 ? (answer as string) : '');
              return (
                <div key={bIdx} className="flex items-center gap-3 animate-in slide-in-from-left-2 duration-300" style={{ transitionDelay: `${bIdx * 50}ms` }}>
                  {question.correctAnswers.length > 1 && (
                    <span className="text-xs font-black text-slate-300 select-none">({bIdx + 1})</span>
                  )}
                  <input
                    type="text"
                    placeholder={`Answer for blank ${bIdx + 1}...`}
                    value={currentVal}
                    onChange={(e) => handleBlankChange(bIdx, e.target.value)}
                    className="flex-grow p-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                    disabled={isGraded}
                  />
                </div>
              );
            })}
          </div>
        )}

        {question.type === QuestionType.SUBJECTIVE && (
          <textarea
            placeholder="Write your answer in detail..."
            rows={4}
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
            disabled={isGraded}
          />
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSet, UserAnswers, QuestionType, GradeResult, Question } from '../types';
import { Button } from './Button';
import { QuestionRenderer } from './QuestionRenderer';
import { Dialog } from './Dialog';

interface QuizTakerProps {
  quiz: QuizSet;
  onExit: () => void;
}

export const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, onExit }) => {
  const [answers, setAnswers] = useState<UserAnswers>({});
  const [confusedIds, setConfusedIds] = useState<Set<string>>(new Set());
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [grades, setGrades] = useState<GradeResult[]>([]);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const handleAnswerChange = (qId: string, value: string | string[]) => {
    setAnswers(prev => ({ ...prev, [qId]: value }));
  };

  const toggleConfusion = (qId: string) => {
    setConfusedIds(prev => {
      const next = new Set(prev);
      if (next.has(qId)) next.delete(qId);
      else next.add(qId);
      return next;
    });
  };

  const scrollToQuestion = (id: string) => {
    const el = document.getElementById(`q-container-${id}`);
    if (el) {
      const offset = 100; // Account for sticky header
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = el.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  const calculateGrade = () => {
    const results: GradeResult[] = quiz.questions.map(q => {
      const userAns = answers[q.id];
      let isCorrect = false;
      let score = 0;
      switch (q.type) {
        case QuestionType.SINGLE_CHOICE:
        case QuestionType.TRUE_FALSE:
          isCorrect = userAns === q.correctAnswers[0];
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.MULTIPLE_CHOICE:
          const sortedCorrect = [...q.correctAnswers].sort().join(',');
          const sortedUser = Array.isArray(userAns) ? [...userAns].sort().join(',') : '';
          isCorrect = sortedCorrect === sortedUser;
          score = isCorrect ? q.points : 0;
          break;
        case QuestionType.FILL_IN_THE_BLANK:
          const userArr = Array.isArray(userAns) ? userAns : [userAns as string || ''];
          let correctBlanks = 0;
          q.correctAnswers.forEach((correctVal, idx) => {
            const userVal = (userArr[idx] || '').trim().toLowerCase();
            // Support synonyms with |
            const synonyms = correctVal.split('|').map(s => s.trim().toLowerCase());
            if (synonyms.includes(userVal)) {
              correctBlanks++;
            }
          });
          isCorrect = correctBlanks === q.correctAnswers.length;
          // Partial credit:
          score = q.correctAnswers.length > 0 ? Math.floor((correctBlanks / q.correctAnswers.length) * q.points) : 0;
          break;
        case QuestionType.SUBJECTIVE:
          isCorrect = true; 
          score = 0;
          break;
      }
      return { questionId: q.id, isCorrect, score, maxScore: q.points };
    });
    setGrades(results);
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const getStandardAnswerDisplay = (q: Question) => {
    if (q.type === QuestionType.SINGLE_CHOICE || q.type === QuestionType.MULTIPLE_CHOICE) {
      return q.correctAnswers
        .map(ansId => q.options?.find(o => o.id === ansId)?.text || ansId)
        .join(', ');
    }
    if (q.type === QuestionType.FILL_IN_THE_BLANK) {
      return q.correctAnswers.map((ans, i) => `(${i+1}) ${ans}`).join('; ');
    }
    return q.correctAnswers.join(' / ');
  };

  const answeredCount = quiz.questions.filter(q => {
    const val = answers[q.id];
    if (val === undefined) return false;
    if (Array.isArray(val)) return val.some(v => v.trim().length > 0);
    return val.trim().length > 0;
  }).length;

  const totalScore = grades.reduce((acc, g) => acc + g.score, 0);
  const maxScore = quiz.questions.reduce((acc, q) => q.type !== QuestionType.SUBJECTIVE ? acc + q.points : acc, 0);

  return (
    <div className="relative max-w-7xl mx-auto px-4 pb-20 flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      <Dialog 
        isOpen={showExitConfirm}
        onClose={() => setShowExitConfirm(false)}
        onConfirm={onExit}
        type="confirm"
        title="Exit Quiz?"
        message="Your progress will not be saved. Are you sure you want to end this session?"
        confirmText="Exit Session"
      />

      <div className="w-full lg:max-w-4xl space-y-8">
        <div className="mb-8">
          <h1 className="text-3xl font-extrabold text-slate-800 mb-2">
            {isSubmitted ? 'Test Report: ' : ''}{quiz.title}
          </h1>
          <p className="text-slate-500">{quiz.description}</p>
        </div>

        <div className="space-y-12">
          {quiz.questions.map((q, idx) => {
            const grade = grades.find(g => g.questionId === q.id);
            return (
              <div key={q.id} id={`q-container-${q.id}`} className="space-y-4">
                <QuestionRenderer
                  question={q} 
                  index={idx}
                  answer={answers[q.id] || (q.type === QuestionType.MULTIPLE_CHOICE || q.type === QuestionType.FILL_IN_THE_BLANK ? [] : '')}
                  onChange={(val) => handleAnswerChange(q.id, val)}
                  isGraded={isSubmitted}
                  isConfused={confusedIds.has(q.id)}
                  onToggleConfusion={() => toggleConfusion(q.id)}
                />
                {isSubmitted && (
                  <div className={`p-6 rounded-2xl border ${
                    q.type === QuestionType.SUBJECTIVE 
                      ? 'bg-amber-50 border-amber-100 text-amber-800' 
                      : (grade?.isCorrect ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : (grade && grade.score > 0 ? 'bg-blue-50 border-blue-100 text-blue-800' : 'bg-red-50 border-red-100 text-red-800'))
                  }`}>
                    <div className="flex justify-between items-center mb-4">
                       <span className="font-bold">
                         {q.type === QuestionType.SUBJECTIVE 
                           ? 'Subjective Reference' 
                           : (grade?.isCorrect ? '✓ CORRECT' : (grade && grade.score > 0 ? '⚠ PARTIAL' : '✗ INCORRECT'))
                         }
                       </span>
                       <span className="text-sm font-bold">
                         Score: {grade?.score} / {grade?.maxScore}
                       </span>
                    </div>
                    {q.type !== QuestionType.SUBJECTIVE ? (
                      <div className="text-sm opacity-80 font-medium">
                        Standard Answer: <span>{getStandardAnswerDisplay(q)}</span>
                      </div>
                    ) : (
                      <div className="text-sm">
                        <span className="font-bold block mb-1">Grading Reference:</span>
                        <p className="whitespace-pre-wrap opacity-90">{q.subjectiveReference || "No reference provided."}</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Navigator Sidebar */}
      <aside className="w-full lg:w-80 lg:sticky lg:top-24 z-30 order-first lg:order-last">
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-xl space-y-6">
          <div>
             <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-4">
               {isSubmitted ? 'Final Result' : 'Question Navigator'}
             </h3>

             <div className="grid grid-cols-5 gap-2 mb-6">
                {quiz.questions.map((q, idx) => {
                  const hasAnswer = answers[q.id] && (Array.isArray(answers[q.id]) ? (answers[q.id] as string[]).some(v => v.trim().length > 0) : (answers[q.id] as string).trim().length > 0);
                  const isConfused = confusedIds.has(q.id);
                  const grade = grades.find(g => g.questionId === q.id);

                  let statusClass = "bg-slate-50 text-slate-400 border-slate-100";
                  if (isSubmitted) {
                    if (q.type === QuestionType.SUBJECTIVE) statusClass = "bg-amber-500 text-white border-amber-600";
                    else if (grade?.isCorrect) statusClass = "bg-emerald-500 text-white border-emerald-600";
                    else if (grade && grade.score > 0) statusClass = "bg-blue-500 text-white border-blue-600";
                    else statusClass = "bg-red-500 text-white border-red-600";
                  } else if (hasAnswer) {
                    statusClass = "bg-indigo-600 text-white border-indigo-700 shadow-sm";
                  }

                  return (
                    <button
                      key={q.id}
                      onClick={() => scrollToQuestion(q.id)}
                      className={`relative h-10 w-full rounded-lg border text-xs font-bold flex items-center justify-center transition-all hover:scale-105 active:scale-95 ${statusClass} ${isConfused ? 'ring-2 ring-yellow-400' : ''}`}
                    >
                      {idx + 1}
                      {isConfused && (
                        <span className="absolute -top-1 -right-1 w-3 h-3 bg-yellow-400 border-2 border-white rounded-full shadow-sm"></span>
                      )}
                    </button>
                  );
                })}
             </div>

             <div className="pt-4 border-t border-slate-50 space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <span className="text-slate-500">{isSubmitted ? 'Total Score' : 'Completion'}</span>
                  <span className="font-black text-indigo-600 text-lg">
                    {isSubmitted ? `${totalScore} / ${maxScore}` : `${answeredCount} / ${quiz.questions.length}`}
                  </span>
                </div>
                {!isSubmitted && (
                  <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                    <div 
                      className="bg-indigo-600 h-full transition-all duration-500" 
                      style={{ width: `${(answeredCount / quiz.questions.length) * 100}%` }}
                    ></div>
                  </div>
                )}
             </div>
          </div>

          <div className="flex flex-col gap-2 pt-2">
             {!isSubmitted ? (
               <Button variant="primary" className="w-full py-4 shadow-lg shadow-indigo-100" onClick={calculateGrade}>
                 Submit Quiz
               </Button>
             ) : (
               <Button variant="primary" className="w-full py-4 shadow-lg shadow-emerald-100" onClick={onExit}>
                 Finish & Exit
               </Button>
             )}
             <Button variant="ghost" onClick={() => setShowExitConfirm(true)}>
               {isSubmitted ? 'Close Report' : 'Quit Session'}
             </Button>
          </div>
        </div>
      </aside>
    </div>
  );
};

