import React, { useState, useEffect, useRef } from 'react';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { DevDocs } from './components/DevDocs';
import { Dialog, DialogType } from './components/Dialog';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';

export default function App() {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [sessionQuiz, setSessionQuiz] = useState<QuizSet | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);
  const [showStartPrompt, setShowStartPrompt] = useState<QuizSet | null>(null);
  const [showRandomPrompt, setShowRandomPrompt] = useState<QuizSet | null>(null);
  const [randomN, setRandomN] = useState<number>(5);
  const [showDevDocs, setShowDevDocs] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string>('');
  const [isImporting, setIsImporting] = useState(false);

  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    type: DialogType;
    onConfirm?: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    type: 'info'
  });

  const showAlert = (title: string, message: string, type: DialogType = 'info') => {
    setDialog({ isOpen: true, title, message, type });
  };

  const showConfirm = (title: string, message: string, onConfirm: () => void) => {
    setDialog({ isOpen: true, title, message, type: 'confirm', onConfirm });
  };

  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  useEffect(() => {
    if (showShareModal) {
      const quiz = quizzes.find(q => q.id === showShareModal);
      if (quiz) {
        encodeQuizKey(quiz).then(key => {
          setGeneratedKey(key);
        });
      }
    } else {
      setGeneratedKey('');
    }
  }, [showShareModal, quizzes]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setSessionQuiz(null);
  };

  const performImport = async (key: string) => {
    if (!key.trim()) return;
    setIsImporting(true);
    const decoded = await decodeQuizKey(key.trim());
    setIsImporting(false);

    if (decoded) {
      if (quizzes.some(q => q.id === decoded.id)) {
        showAlert("Duplicate Quiz", "This quiz is already in your library.", "warning");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        showAlert("Success", `Successfully imported: ${decoded.title}`, "success");
        return true;
      }
    } else {
      showAlert("Import Failed", "Invalid share key. Please ensure you copied the full key.", "error");
    }
    return false;
  };

  const handleImport = () => performImport(importKey);

  const handleDelete = (id: string) => {
    showConfirm("Delete Quiz", "This action will vaporize this quiz set. Proceed?", () => {
      setQuizzes(quizzes.filter(q => q.id !== id));
    });
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const startQuizSession = (quiz: QuizSet, shuffle: boolean) => {
    const quizToRun = shuffle 
      ? { ...quiz, questions: shuffleArray(quiz.questions) } 
      : { ...quiz };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowStartPrompt(null);
  };

  const startRandomQuizSession = (quiz: QuizSet, count: number) => {
    const total = quiz.questions.length;
    const n = Math.max(1, Math.min(count, total));
    const shuffled = shuffleArray(quiz.questions);
    const selected = shuffled.slice(0, n);

    const quizToRun = { 
      ...quiz, 
      title: `${quiz.title} (Random ${n})`,
      questions: selected 
    };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowRandomPrompt(null);
  };

  const renderHome = () => (
    <div className="space-y-20">
      <section className="relative py-24 px-8 overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full bg-violet-600 rounded-[3rem] -rotate-1 scale-105 z-0"></div>
        <div className="absolute top-0 left-0 w-full h-full bg-slate-900 rounded-[3rem] z-10 border-4 border-slate-900"></div>

        <div className="relative z-20 text-center max-w-4xl mx-auto flex flex-col items-center">
          <div className="bg-emerald-400 border-2 border-slate-900 px-4 py-1 rounded-full mb-6 inline-block rotate-2 neo-shadow">
            <span className="text-[12px] font-black uppercase text-slate-900 tracking-widest">Self-Testing Reimagined</span>
          </div>
          <h1 className="text-6xl md:text-8xl font-display text-white mb-6 leading-tight">
            Knowledge is <span className="text-violet-400">Power</span>.
          </h1>
          <p className="text-slate-400 text-xl mb-12 max-w-2xl leading-relaxed font-light">
            Create, share, and master any subject with our ultra-compressed quiz engine. Designed for thinkers, makers, and lifelong learners.
          </p>

          <div className="flex flex-col md:flex-row gap-6 w-full max-w-2xl justify-center items-center">
            <Button size="lg" variant="success" className="w-full md:w-auto px-10" onClick={() => setCurrentView('CREATE')}>
              Start Creating
            </Button>

            <div className="flex-grow w-full flex items-stretch border-4 border-slate-900 rounded-2xl overflow-hidden bg-slate-800 neo-shadow">
              <input 
                type="text" 
                placeholder="Paste your Secret Key..." 
                className="bg-transparent px-6 py-4 outline-none text-white placeholder-slate-500 w-full font-mono text-sm"
                value={importKey}
                onChange={(e) => setImportKey(e.target.value)}
              />
              <button 
                className="bg-emerald-400 px-6 py-4 font-black text-slate-900 border-l-4 border-slate-900 hover:bg-emerald-300 transition-colors"
                onClick={handleImport}
                disabled={isImporting}
              >
                {isImporting ? '...' : 'IMPORT'}
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="px-4">
        <div className="flex items-center justify-between mb-12">
          <div>
            <h2 className="text-4xl font-display text-slate-900">Your Archive</h2>
            <p className="text-slate-500 font-medium">Your personalized collection of challenges</p>
          </div>
          <div className="hidden md:flex items-center gap-2">
            <span className="w-12 h-12 rounded-full border-2 border-slate-900 flex items-center justify-center font-black text-violet-600 bg-violet-50">
              {quizzes.length}
            </span>
          </div>
        </div>

        {quizzes.length === 0 ? (
          <div className="text-center py-24 bg-white border-4 border-slate-200 rounded-[40px] border-dashed">
            <div className="mb-6 text-slate-200 text-9xl font-display opacity-50">EMPTY</div>
            <p className="text-slate-400 text-xl font-medium">Your archive is awaiting its first contribution.</p>
            <Button variant="ghost" className="mt-8" onClick={() => setCurrentView('CREATE')}>Create a quiz now →</Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { 
                  const q = quizzes.find(item => item.id === id);
                  if (q) setShowStartPrompt(q);
                }}
                onRandomStart={(id) => {
                  const q = quizzes.find(item => item.id === id);
                  if (q) {
                    setShowRandomPrompt(q);
                    setRandomN(Math.min(5, q.questions.length));
                  }
                }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>
    </div>
  );

  return (
    <div className="min-h-screen pb-20">
      <nav className="h-20 flex items-center px-10 max-w-7xl mx-auto mb-10">
        <div className="w-full flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setCurrentView('HOME')}>
            <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center neo-shadow group-hover:rotate-6 transition-transform">
              <svg className="w-6 h-6 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
            </div>
            <span className="font-display text-2xl tracking-tighter text-slate-900">Quiz<span className="text-violet-600">Genius</span></span>
          </div>
          <div className="flex items-center gap-6">
             <button className="text-xs font-black uppercase tracking-widest text-slate-500 hover:text-slate-900 transition-colors" onClick={() => setShowDevDocs(true)}>Guidelines</button>
             {currentView !== 'HOME' && <Button variant="secondary" size="sm" onClick={() => setCurrentView('HOME')}>Back Home</Button>}
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6">
        {currentView === 'HOME' && renderHome()}
        {currentView === 'CREATE' && <QuizEditor onSave={handleSaveQuiz} onCancel={() => setCurrentView('HOME')} />}
        {currentView === 'QUIZ' && sessionQuiz && <QuizTaker quiz={sessionQuiz} onExit={() => { setCurrentView('HOME'); setSessionQuiz(null); }} />}
      </main>

      {/* Global Modals with stylized looks */}
      {showDevDocs && <DevDocs onClose={() => setShowDevDocs(false)} />}

      {showStartPrompt && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[40px] border-4 border-slate-900 p-10 max-w-sm w-full neo-shadow animate-in zoom-in-95">
            <h3 className="text-3xl font-display text-slate-900 mb-4">Ready to test?</h3>
            <p className="text-slate-500 mb-8 font-medium italic">"Shuffle the deck to challenge your patterns, not just your memory."</p>
            <div className="space-y-4">
              <Button variant="primary" className="w-full py-5" onClick={() => startQuizSession(showStartPrompt, true)}>Randomize Order</Button>
              <Button variant="secondary" className="w-full py-5" onClick={() => startQuizSession(showStartPrompt, false)}>Keep it Static</Button>
              <button className="w-full text-xs font-black uppercase text-slate-400 mt-2" onClick={() => setShowStartPrompt(null)}>Abandon Session</button>
            </div>
          </div>
        </div>
      )}

      {showShareModal && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[40px] border-4 border-slate-900 p-10 max-w-2xl w-full neo-shadow animate-in zoom-in-95">
            <div className="flex items-center gap-4 mb-8">
               <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
               </div>
               <div>
                 <h3 className="text-3xl font-display text-slate-900">Your Share Key</h3>
                 <p className="text-slate-400 text-sm uppercase font-black tracking-widest">Ultra-Compressed / V2 Protocol</p>
               </div>
            </div>

            <div className="bg-slate-900 p-8 rounded-3xl border-2 border-slate-900 mb-8 relative group overflow-hidden">
               <textarea 
                 readOnly 
                 className="w-full bg-transparent text-[11px] font-mono h-48 outline-none resize-none scrollbar-hide leading-relaxed text-emerald-400/80" 
                 value={generatedKey} 
                 onClick={(e) => (e.target as HTMLTextAreaElement).select()}
               />
               <div className="absolute top-2 right-4 text-[9px] font-black text-slate-600 uppercase">Secure Stream</div>
            </div>

            <div className="flex gap-4">
              <Button className="flex-grow py-5" onClick={() => {
                navigator.clipboard.writeText(generatedKey);
                showAlert("Copied!", "Your encrypted key is ready for transport.", "success");
              }}>Copy to Clipboard</Button>
              <Button variant="ghost" className="px-10" onClick={() => setShowShareModal(null)}>Dismiss</Button>
            </div>
          </div>
        </div>
      )}

      <Dialog 
        isOpen={dialog.isOpen}
        onClose={() => setDialog(prev => ({ ...prev, isOpen: false }))}
        onConfirm={dialog.onConfirm}
        title={dialog.title}
        message={dialog.message}
        type={dialog.type}
      />
    </div>
  );
}

import React from 'react';
import { Question, QuestionType } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: string | string[];
  onChange: (value: string | string[]) => void;
  isGraded?: boolean;
  isConfused?: boolean;
  onToggleConfusion?: () => void;
}

export const QuestionRenderer: React.FC<QuestionRendererProps> = ({
  question,
  index,
  answer,
  onChange,
  isGraded = false,
  isConfused = false,
  onToggleConfusion
}) => {
  const handleSingleChoice = (optionId: string) => {
    if (isGraded) return;
    onChange(optionId);
  };

  const handleMultipleChoice = (optionId: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) ? answer : [];
    if (currentAnswers.includes(optionId)) {
      onChange(currentAnswers.filter(id => id !== optionId));
    } else {
      onChange([...currentAnswers, optionId]);
    }
  };

  const handleTrueFalse = (val: string) => {
    if (isGraded) return;
    onChange(val);
  };

  const handleBlankChange = (blankIdx: number, val: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) 
      ? [...answer] 
      : new Array(question.correctAnswers.length).fill('');
    currentAnswers[blankIdx] = val;
    onChange(currentAnswers);
  };

  return (
    <div className={`p-8 rounded-[30px] bg-white border-2 border-slate-900 relative transition-all neo-shadow ${
      isConfused && !isGraded ? 'bg-amber-50 ring-4 ring-amber-400' : ''
    }`}>

      {/* Confusion Toggle - Stylized */}
      {!isGraded && onToggleConfusion && (
        <button
          onClick={(e) => {
            e.preventDefault();
            onToggleConfusion();
          }}
          className={`absolute -top-4 -right-4 w-12 h-12 rounded-2xl border-2 border-slate-900 flex items-center justify-center transition-all ${
            isConfused 
              ? 'bg-amber-400 text-slate-900 neo-shadow rotate-12' 
              : 'bg-white text-slate-300 hover:text-amber-500 hover:rotate-12'
          }`}
        >
          <span className="font-display text-2xl">?</span>
        </button>
      )}

      <div className="flex flex-col md:flex-row items-start gap-6 mb-8">
        <div className="flex-shrink-0 w-16 h-16 rounded-2xl bg-slate-900 border-2 border-slate-900 text-white flex items-center justify-center font-display text-2xl -rotate-2 neo-shadow">
          {index + 1}
        </div>
        <div className="flex-grow">
          <div className="flex items-center gap-3 mb-2">
             <span className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-500 bg-violet-50 px-2 py-0.5 rounded border border-violet-100">
               {question.type.replace(/_/g, ' ')}
             </span>
             <span className="text-[10px] font-black text-slate-400 tracking-tighter uppercase">• {question.points} Points Available</span>
          </div>
          <h4 className="text-2xl font-display text-slate-900 leading-tight whitespace-pre-wrap">{question.text}</h4>
        </div>
      </div>

      <div className="md:ml-20 space-y-4">
        {question.type === QuestionType.SINGLE_CHOICE && question.options?.map((opt, i) => (
          <label 
            key={opt.id} 
            className={`flex items-center p-4 rounded-2xl border-2 transition-all cursor-pointer ${
              answer === opt.id 
                ? 'border-slate-900 bg-violet-500 text-white neo-shadow translate-x-1' 
                : 'border-slate-100 hover:border-slate-300 text-slate-700'
            } ${isGraded ? 'pointer-events-none opacity-80' : ''}`}
          >
            <div className={`w-8 h-8 rounded-lg border-2 border-slate-900 flex items-center justify-center mr-4 text-xs font-black ${answer === opt.id ? 'bg-white text-violet-600' : 'bg-slate-50 text-slate-400'}`}>
               {String.fromCharCode(65 + i)}
            </div>
            <input type="radio" className="hidden" checked={answer === opt.id} onChange={() => handleSingleChoice(opt.id)} />
            <span className="font-bold">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.MULTIPLE_CHOICE && question.options?.map((opt, i) => (
          <label 
            key={opt.id} 
            className={`flex items-center p-4 rounded-2xl border-2 transition-all cursor-pointer ${
              Array.isArray(answer) && answer.includes(opt.id) 
                ? 'border-slate-900 bg-emerald-400 text-slate-900 neo-shadow translate-x-1' 
                : 'border-slate-100 hover:border-slate-300 text-slate-700'
            } ${isGraded ? 'pointer-events-none opacity-80' : ''}`}
          >
            <div className={`w-8 h-8 rounded-lg border-2 border-slate-900 flex items-center justify-center mr-4 text-xs font-black ${Array.isArray(answer) && answer.includes(opt.id) ? 'bg-white text-emerald-600' : 'bg-slate-50 text-slate-400'}`}>
               {String.fromCharCode(65 + i)}
            </div>
            <input type="checkbox" className="hidden" checked={Array.isArray(answer) && answer.includes(opt.id)} onChange={() => handleMultipleChoice(opt.id)} />
            <span className="font-bold">{opt.text}</span>
          </label>
        ))}

        {question.type === QuestionType.TRUE_FALSE && (
          <div className="flex gap-6">
            {['true', 'false'].map(val => (
              <button
                key={val}
                onClick={() => handleTrueFalse(val)}
                className={`flex-1 py-5 rounded-2xl border-2 font-black capitalize transition-all neo-shadow ${
                  answer === val 
                    ? 'border-slate-900 bg-emerald-400 text-slate-900' 
                    : 'border-slate-100 text-slate-400 hover:border-slate-300'
                } ${isGraded ? 'pointer-events-none' : ''}`}
              >
                {val}
              </button>
            ))}
          </div>
        )}

        {question.type === QuestionType.FILL_IN_THE_BLANK && (
          <div className="space-y-4">
            {question.correctAnswers.map((_, bIdx) => {
              const currentVal = Array.isArray(answer) ? (answer[bIdx] || '') : (bIdx === 0 ? (answer as string) : '');
              return (
                <div key={bIdx} className="flex items-center gap-4">
                  <div className="w-8 h-8 flex-shrink-0 bg-slate-900 text-white text-[10px] font-black rounded-lg flex items-center justify-center">
                    {bIdx + 1}
                  </div>
                  <input
                    type="text"
                    placeholder={`Answer for entry ${bIdx + 1}...`}
                    value={currentVal}
                    onChange={(e) => handleBlankChange(bIdx, e.target.value)}
                    className="flex-grow p-4 rounded-2xl border-2 border-slate-900 focus:bg-violet-50 outline-none transition-all font-bold placeholder:font-normal placeholder:opacity-30"
                    disabled={isGraded}
                  />
                </div>
              );
            })}
          </div>
        )}

        {question.type === QuestionType.SUBJECTIVE && (
          <textarea
            placeholder="Document your full reasoning here..."
            rows={6}
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className="w-full p-6 rounded-[30px] border-2 border-slate-900 focus:bg-violet-50 outline-none transition-all font-bold placeholder:font-normal"
            disabled={isGraded}
          />
        )}
      </div>
    </div>
  );
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'success';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({
  children,
  variant = 'primary',
  size = 'md',
  isLoading,
  className = '',
  ...props
}) => {
  const isStylized = document.documentElement.classList.contains('theme-stylized');

  const baseStyles = 'inline-flex items-center justify-center font-bold tracking-tight transition-all duration-150 disabled:opacity-50 disabled:cursor-not-allowed';

  const themeStyles = isStylized 
    ? 'border-2 border-slate-900 neo-shadow neo-shadow-hover neo-shadow-active' 
    : 'classic-shadow classic-shadow-hover active:scale-95 border border-transparent';

  const variants = {
    primary: isStylized ? 'bg-violet-500 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-700',
    secondary: isStylized ? 'bg-white text-slate-800' : 'bg-slate-100 text-slate-700 hover:bg-slate-200',
    danger: isStylized ? 'bg-rose-500 text-white' : 'bg-rose-600 text-white hover:bg-rose-700',
    success: isStylized ? 'bg-emerald-400 text-slate-900' : 'bg-emerald-500 text-white hover:bg-emerald-600',
    ghost: 'bg-transparent text-slate-600 border-transparent shadow-none hover:bg-slate-100',
  };

  const sizes = {
    sm: 'px-4 py-1.5 text-xs rounded-lg',
    md: 'px-6 py-2.5 text-sm rounded-xl',
    lg: 'px-8 py-4 text-lg rounded-2xl',
  };

  return (
    <button
      className={`${baseStyles} ${themeStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading && (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      )}
      {children}
    </button>
  );
};

import React from 'react';
import { QuizSet } from '../types';
import { Button } from './Button';

interface QuizCardProps {
  quiz: QuizSet;
  onStart: (id: string) => void;
  onRandomStart: (id: string) => void;
  onShare: (id: string) => void;
