          </div>
          <div className={`${isStylized ? 'bg-emerald-400 border-2 border-slate-900' : 'bg-slate-100 text-slate-500'} px-2 py-1 rounded-lg text-[10px] font-black`}>
            {quiz.questions.length} Qs
