          <Button variant="primary" size="sm" className="w-full" onClick={() => onStart(quiz.id)}>Begin Test</Button>
          <Button variant="secondary" size="sm" className="w-full" onClick={() => onRandomStart(quiz.id)}>Random N</Button>
        </div>

        <div className="flex items-center gap-2 mt-4 pt-4 border-t border-slate-100">
          <button 
            onClick={() => onShare(quiz.id)}
            className={`flex-grow text-left text-xs font-bold transition-colors uppercase tracking-widest ${isStylized ? 'text-slate-400 hover:text-violet-600' : 'text-indigo-500 hover:text-indigo-700'}`}
          >
            Get Share Key →
          </button>
          <button 
            onClick={() => onDelete(quiz.id)}
            className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-rose-50 text-rose-400 hover:text-rose-600 transition-all"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { QuizSet } from './types';
import { QuizCard } from './components/QuizCard';
import { QuizEditor } from './components/QuizEditor';
import { QuizTaker } from './components/QuizTaker';
import { Button } from './components/Button';
import { DevDocs } from './components/DevDocs';
import { Dialog, DialogType } from './components/Dialog';
import { encodeQuizKey, decodeQuizKey } from './utils/codec';

type ViewState = 'HOME' | 'CREATE' | 'QUIZ' | 'EDIT';
type ThemeMode = 'classic' | 'stylized';

export default function App() {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [theme, setTheme] = useState<ThemeMode>(() => {
    const saved = localStorage.getItem('app_theme');
    return (saved as ThemeMode) || 'stylized';
  });
  const [sessionQuiz, setSessionQuiz] = useState<QuizSet | null>(null);
  const [importKey, setImportKey] = useState('');
  const [showShareModal, setShowShareModal] = useState<string | null>(null);
  const [showStartPrompt, setShowStartPrompt] = useState<QuizSet | null>(null);
  const [showRandomPrompt, setShowRandomPrompt] = useState<QuizSet | null>(null);
  const [randomN, setRandomN] = useState<number>(5);
  const [showDevDocs, setShowDevDocs] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string>('');
  const [isImporting, setIsImporting] = useState(false);

  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    type: DialogType;
    onConfirm?: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    type: 'info'
  });

  // Apply theme to document element for global CSS selection
  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'stylized') {
      root.classList.add('theme-stylized');
      root.classList.remove('theme-classic');
    } else {
      root.classList.add('theme-classic');
      root.classList.remove('theme-stylized');
    }
    localStorage.setItem('app_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'classic' ? 'stylized' : 'classic');
  };

  const showAlert = (title: string, message: string, type: DialogType = 'info') => {
    setDialog({ isOpen: true, title, message, type });
  };

  const showConfirm = (title: string, message: string, onConfirm: () => void) => {
    setDialog({ isOpen: true, title, message, type: 'confirm', onConfirm });
  };

  useEffect(() => {
    const saved = localStorage.getItem('my_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load quizzes", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('my_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  useEffect(() => {
    if (showShareModal) {
      const quiz = quizzes.find(q => q.id === showShareModal);
      if (quiz) {
        encodeQuizKey(quiz).then(key => {
          setGeneratedKey(key);
        });
      }
    } else {
      setGeneratedKey('');
    }
  }, [showShareModal, quizzes]);

  const handleSaveQuiz = (quiz: QuizSet) => {
    const exists = quizzes.find(q => q.id === quiz.id);
    if (exists) {
      setQuizzes(quizzes.map(q => q.id === quiz.id ? quiz : q));
    } else {
      setQuizzes([quiz, ...quizzes]);
    }
    setCurrentView('HOME');
    setSessionQuiz(null);
  };

  const performImport = async (key: string) => {
    if (!key.trim()) return;
    setIsImporting(true);
    const decoded = await decodeQuizKey(key.trim());
    setIsImporting(false);

    if (decoded) {
      if (quizzes.some(q => q.id === decoded.id)) {
        showAlert("Duplicate Quiz", "This quiz is already in your library.", "warning");
      } else {
        setQuizzes([decoded, ...quizzes]);
        setImportKey('');
        showAlert("Success", `Successfully imported: ${decoded.title}`, "success");
        return true;
      }
    } else {
      showAlert("Import Failed", "Invalid share key. Please ensure you copied the full key.", "error");
    }
    return false;
  };

  const handleImport = () => performImport(importKey);

  const handleDelete = (id: string) => {
    showConfirm("Delete Quiz", "This action will vaporize this quiz set. Proceed?", () => {
      setQuizzes(quizzes.filter(q => q.id !== id));
    });
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const startQuizSession = (quiz: QuizSet, shuffle: boolean) => {
    const quizToRun = shuffle 
      ? { ...quiz, questions: shuffleArray(quiz.questions) } 
      : { ...quiz };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowStartPrompt(null);
  };

  const startRandomQuizSession = (quiz: QuizSet, count: number) => {
    const total = quiz.questions.length;
    const n = Math.max(1, Math.min(count, total));
    const shuffled = shuffleArray(quiz.questions);
    const selected = shuffled.slice(0, n);

    const quizToRun = { 
      ...quiz, 
      title: `${quiz.title} (Random ${n})`,
      questions: selected 
    };

    setSessionQuiz(quizToRun);
    setCurrentView('QUIZ');
    setShowRandomPrompt(null);
  };

  const isStylized = theme === 'stylized';

  const renderHome = () => (
    <div className="space-y-16 lg:space-y-20">
      <section className={`relative py-24 px-8 overflow-hidden transition-all duration-500 ${isStylized ? '' : 'bg-white rounded-3xl border border-slate-100 shadow-xl'}`}>
        {isStylized && (
          <>
            <div className="absolute top-0 left-0 w-full h-full bg-violet-600 rounded-[3rem] -rotate-1 scale-105 z-0"></div>
            <div className="absolute top-0 left-0 w-full h-full bg-slate-900 rounded-[3rem] z-10 border-4 border-slate-900"></div>
          </>
        )}

        <div className={`relative z-20 text-center max-w-4xl mx-auto flex flex-col items-center ${isStylized ? 'text-white' : 'text-slate-800'}`}>
          <div className={`${isStylized ? 'bg-emerald-400 border-2 border-slate-900 rotate-2 neo-shadow text-slate-900' : 'bg-indigo-50 text-indigo-600'} px-4 py-1 rounded-full mb-6 inline-block`}>
            <span className="text-[12px] font-black uppercase tracking-widest">Self-Testing Reimagined</span>
          </div>

          <h1 className={`text-5xl md:text-7xl lg:text-8xl mb-6 leading-tight ${isStylized ? 'font-display' : 'font-bold tracking-tight'}`}>
            Knowledge is <span className={isStylized ? 'text-violet-400' : 'text-indigo-600'}>Power</span>.
          </h1>

          <p className={`text-lg md:text-xl mb-12 max-w-2xl leading-relaxed ${isStylized ? 'text-slate-400 font-light' : 'text-slate-500 font-medium'}`}>
            Create, share, and master any subject with our ultra-compressed quiz engine. Designed for thinkers, makers, and lifelong learners.
          </p>

          <div className="flex flex-col md:flex-row gap-6 w-full max-w-2xl justify-center items-center">
            <Button size="lg" variant="success" className="w-full md:w-auto px-10" onClick={() => setCurrentView('CREATE')}>
              Start Creating
            </Button>

            <div className={`flex-grow w-full flex items-stretch overflow-hidden transition-all ${isStylized ? 'border-4 border-slate-900 rounded-2xl bg-slate-800 neo-shadow' : 'border border-slate-200 rounded-xl bg-slate-50'}`}>
              <input 
                type="text" 
                placeholder="Paste your Secret Key..." 
                className={`bg-transparent px-6 py-4 outline-none w-full font-mono text-sm ${isStylized ? 'text-white placeholder-slate-500' : 'text-slate-700 placeholder-slate-400'}`}
                value={importKey}
                onChange={(e) => setImportKey(e.target.value)}
              />
              <button 
                className={`px-6 py-4 font-black transition-colors ${isStylized ? 'bg-emerald-400 text-slate-900 border-l-4 border-slate-900 hover:bg-emerald-300' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
                onClick={handleImport}
                disabled={isImporting}
              >
                {isImporting ? '...' : 'IMPORT'}
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="px-4">
        <div className="flex items-center justify-between mb-12">
          <div>
            <h2 className={`text-4xl ${isStylized ? 'font-display text-slate-900' : 'font-bold text-slate-800 tracking-tight'}`}>Your Archive</h2>
            <p className="text-slate-500 font-medium">Your personalized collection of challenges</p>
          </div>
          <div className="hidden md:flex items-center gap-2">
            <span className={`w-12 h-12 rounded-full flex items-center justify-center font-black transition-all ${isStylized ? 'border-2 border-slate-900 text-violet-600 bg-violet-50' : 'bg-indigo-600 text-white shadow-lg shadow-indigo-200'}`}>
              {quizzes.length}
            </span>
          </div>
        </div>

        {quizzes.length === 0 ? (
          <div className={`text-center py-24 bg-white border-dashed border-4 ${isStylized ? 'border-slate-200 rounded-[40px]' : 'border-slate-100 rounded-3xl'}`}>
            <div className={`mb-6 opacity-50 ${isStylized ? 'text-slate-200 text-9xl font-display' : 'text-slate-100 text-8xl font-bold'}`}>EMPTY</div>
            <p className="text-slate-400 text-xl font-medium">Your archive is awaiting its first contribution.</p>
            <Button variant="ghost" className="mt-8" onClick={() => setCurrentView('CREATE')}>Create a quiz now →</Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 lg:gap-10">
            {quizzes.map(quiz => (
              <QuizCard 
                key={quiz.id} 
                quiz={quiz} 
                onStart={(id) => { 
                  const q = quizzes.find(item => item.id === id);
                  if (q) setShowStartPrompt(q);
                }}
                onRandomStart={(id) => {
                  const q = quizzes.find(item => item.id === id);
                  if (q) {
                    setShowRandomPrompt(q);
                    setRandomN(Math.min(5, q.questions.length));
                  }
                }}
                onShare={(id) => setShowShareModal(id)}
                onDelete={handleDelete}
              />
            ))}
          </div>
        )}
      </section>
    </div>
  );

  return (
    <div className={`min-h-screen pb-20 transition-colors duration-500 ${isStylized ? 'bg-[#f8fafc]' : 'bg-slate-50'}`}>
      <nav className="h-24 flex items-center px-6 lg:px-10 max-w-7xl mx-auto mb-6">
        <div className="w-full flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setCurrentView('HOME')}>
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isStylized ? 'bg-slate-900 neo-shadow group-hover:rotate-6' : 'bg-indigo-600 shadow-lg group-hover:scale-110'}`}>
              <svg className={`w-6 h-6 ${isStylized ? 'text-emerald-400' : 'text-white'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
            </div>
            <span className={`text-2xl tracking-tighter ${isStylized ? 'font-display text-slate-900' : 'font-bold text-slate-800'}`}>Quiz<span className={isStylized ? 'text-violet-600' : 'text-indigo-600'}>Genius</span></span>
          </div>

          <div className="flex items-center gap-4 lg:gap-8">
             <button 
                onClick={toggleTheme}
                className={`p-2 rounded-xl border flex items-center gap-2 transition-all ${isStylized ? 'border-slate-900 bg-white neo-shadow hover:translate-y-[-1px]' : 'border-slate-200 bg-white hover:bg-slate-50'}`}
                title="Switch Style"
             >
               {isStylized ? (
                 <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z" /></svg>
               ) : (
                 <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z" /></svg>
               )}
               <span className="text-xs font-black uppercase tracking-widest hidden sm:inline">{isStylized ? 'Classic' : 'Stylized'}</span>
             </button>

             <button className="text-xs font-black uppercase tracking-widest text-slate-500 hover:text-slate-900 transition-colors" onClick={() => setShowDevDocs(true)}>Guidelines</button>
             {currentView !== 'HOME' && <Button variant="secondary" size="sm" onClick={() => setCurrentView('HOME')}>Back Home</Button>}
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6">
        {currentView === 'HOME' && renderHome()}
        {currentView === 'CREATE' && <QuizEditor onSave={handleSaveQuiz} onCancel={() => setCurrentView('HOME')} />}
        {currentView === 'QUIZ' && sessionQuiz && <QuizTaker quiz={sessionQuiz} onExit={() => { setCurrentView('HOME'); setSessionQuiz(null); }} />}
      </main>

      {/* Global Modals */}
      {showDevDocs && <DevDocs onClose={() => setShowDevDocs(false)} />}

      {showStartPrompt && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className={`bg-white p-10 max-w-sm w-full transition-all ${isStylized ? 'rounded-[40px] border-4 border-slate-900 neo-shadow' : 'rounded-3xl shadow-2xl'}`}>
            <h3 className={`text-3xl mb-4 ${isStylized ? 'font-display text-slate-900' : 'font-bold text-slate-800'}`}>Ready to test?</h3>
            <p className="text-slate-500 mb-8 font-medium italic">"Shuffle the deck to challenge your patterns, not just your memory."</p>
            <div className="space-y-4">
              <Button variant="primary" className="w-full py-5" onClick={() => startQuizSession(showStartPrompt, true)}>Randomize Order</Button>
              <Button variant="secondary" className="w-full py-5" onClick={() => startQuizSession(showStartPrompt, false)}>Keep it Static</Button>
              <button className="w-full text-xs font-black uppercase text-slate-400 mt-2" onClick={() => setShowStartPrompt(null)}>Abandon Session</button>
            </div>
          </div>
        </div>
      )}

      {showShareModal && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className={`bg-white p-10 max-w-2xl w-full transition-all ${isStylized ? 'rounded-[40px] border-4 border-slate-900 neo-shadow' : 'rounded-3xl shadow-2xl'}`}>
            <div className="flex items-center gap-4 mb-8">
               <div className={`w-16 h-16 rounded-full flex items-center justify-center ${isStylized ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
               </div>
               <div>
                 <h3 className={`text-3xl ${isStylized ? 'font-display text-slate-900' : 'font-bold text-slate-800'}`}>Your Share Key</h3>
                 <p className="text-slate-400 text-sm uppercase font-black tracking-widest">Ultra-Compressed / V2 Protocol</p>
               </div>
            </div>

            <div className={`p-8 rounded-3xl mb-8 relative group overflow-hidden ${isStylized ? 'bg-slate-900 border-2 border-slate-900' : 'bg-slate-50 border border-slate-200'}`}>
               <textarea 
                 readOnly 
                 className={`w-full bg-transparent text-[11px] font-mono h-48 outline-none resize-none scrollbar-hide leading-relaxed ${isStylized ? 'text-emerald-400/80' : 'text-slate-600'}`} 
                 value={generatedKey} 
                 onClick={(e) => (e.target as HTMLTextAreaElement).select()}
               />
               <div className={`absolute top-2 right-4 text-[9px] font-black uppercase ${isStylized ? 'text-slate-600' : 'text-slate-400'}`}>Secure Stream</div>
            </div>

            <div className="flex gap-4">
              <Button className="flex-grow py-5" onClick={() => {
                navigator.clipboard.writeText(generatedKey);
                showAlert("Copied!", "Your encrypted key is ready for transport.", "success");
              }}>Copy to Clipboard</Button>
              <Button variant="ghost" className="px-10" onClick={() => setShowShareModal(null)}>Dismiss</Button>
            </div>
          </div>
        </div>
      )}

      <Dialog 
        isOpen={dialog.isOpen}
        onClose={() => setDialog(prev => ({ ...prev, isOpen: false }))}
        onConfirm={dialog.onConfirm}
        title={dialog.title}
        message={dialog.message}
        type={dialog.type}
      />
    </div>
  );
}

import React from 'react';
import { Question, QuestionType } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: string | string[];
  onChange: (value: string | string[]) => void;
  isGraded?: boolean;
  isConfused?: boolean;
  onToggleConfusion?: () => void;
}

export const QuestionRenderer: React.FC<QuestionRendererProps> = ({
  question,
  index,
  answer,
  onChange,
  isGraded = false,
  isConfused = false,
  onToggleConfusion
}) => {
  const isStylized = document.documentElement.classList.contains('theme-stylized');

  const handleSingleChoice = (optionId: string) => {
    if (isGraded) return;
    onChange(optionId);
  };

  const handleMultipleChoice = (optionId: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) ? answer : [];
    if (currentAnswers.includes(optionId)) {
      onChange(currentAnswers.filter(id => id !== optionId));
    } else {
      onChange([...currentAnswers, optionId]);
    }
  };

  const handleTrueFalse = (val: string) => {
    if (isGraded) return;
    onChange(val);
  };

  const handleBlankChange = (blankIdx: number, val: string) => {
    if (isGraded) return;
    const currentAnswers = Array.isArray(answer) 
      ? [...answer] 
      : new Array(question.correctAnswers.length).fill('');
    currentAnswers[blankIdx] = val;
    onChange(currentAnswers);
  };

  const cardBaseStyles = isStylized 
    ? `p-8 rounded-[30px] border-2 border-slate-900 neo-shadow ${isConfused && !isGraded ? 'bg-amber-50 ring-4 ring-amber-400' : 'bg-white'}`
    : `p-8 rounded-2xl border ${isConfused && !isGraded ? 'border-amber-400 bg-amber-50 shadow-lg' : 'border-slate-200 bg-white shadow-sm'}`;

  return (
    <div className={`relative transition-all duration-300 ${cardBaseStyles}`}>

      {/* Confusion Toggle */}
      {!isGraded && onToggleConfusion && (
        <button
          onClick={(e) => {
            e.preventDefault();
            onToggleConfusion();
          }}
          className={`absolute -top-4 -right-4 w-12 h-12 flex items-center justify-center transition-all ${
            isStylized 
              ? `rounded-2xl border-2 border-slate-900 ${isConfused ? 'bg-amber-400 text-slate-900 neo-shadow rotate-12' : 'bg-white text-slate-300 hover:text-amber-500'}`
              : `rounded-xl border border-slate-200 shadow-md ${isConfused ? 'bg-amber-500 text-white' : 'bg-white text-slate-400 hover:bg-slate-50'}`
          }`}
        >
          <span className={`${isStylized ? 'font-display text-2xl' : 'font-bold text-lg'}`}>?</span>
        </button>
      )}

      <div className="flex flex-col md:flex-row items-start gap-6 mb-8">
        <div className={`flex-shrink-0 w-16 h-16 flex items-center justify-center text-2xl transition-all ${
          isStylized 
            ? 'rounded-2xl bg-slate-900 border-2 border-slate-900 text-white font-display -rotate-2 neo-shadow'
            : 'rounded-xl bg-indigo-600 text-white font-bold shadow-lg'
        }`}>
          {index + 1}
        </div>
        <div className="flex-grow">
          <div className="flex items-center gap-3 mb-2">
             <span className={`text-[10px] font-black uppercase tracking-[0.2em] px-2 py-0.5 rounded border ${
               isStylized ? 'text-violet-500 bg-violet-50 border-violet-100' : 'text-indigo-500 bg-indigo-50 border-indigo-100'
             }`}>
               {question.type.replace(/_/g, ' ')}
             </span>
             <span className="text-[10px] font-black text-slate-400 tracking-tighter uppercase">• {question.points} Points Available</span>
          </div>
          <h4 className={`text-2xl leading-tight whitespace-pre-wrap ${isStylized ? 'font-display text-slate-900' : 'font-bold text-slate-800'}`}>{question.text}</h4>
        </div>
      </div>

      <div className="md:ml-20 space-y-4">
        {question.type === QuestionType.SINGLE_CHOICE && question.options?.map((opt, i) => {
          const isSelected = answer === opt.id;
          return (
            <label 
              key={opt.id} 
              className={`flex items-center p-4 rounded-2xl border-2 transition-all cursor-pointer ${
                isStylized 
                  ? (isSelected ? 'border-slate-900 bg-violet-500 text-white neo-shadow translate-x-1' : 'border-slate-100 hover:border-slate-300 text-slate-700')
                  : (isSelected ? 'border-indigo-600 bg-indigo-50 text-indigo-700 shadow-sm' : 'border-slate-100 hover:bg-slate-50 text-slate-600')
              } ${isGraded ? 'pointer-events-none opacity-80' : ''}`}
            >
              <div className={`w-8 h-8 rounded-lg border flex items-center justify-center mr-4 text-xs font-black transition-all ${
                isStylized 
                  ? (isSelected ? 'bg-white text-violet-600 border-slate-900' : 'bg-slate-50 text-slate-400 border-slate-200')
                  : (isSelected ? 'bg-indigo-600 text-white border-transparent' : 'bg-white text-slate-300 border-slate-200')
              }`}>
                 {String.fromCharCode(65 + i)}
              </div>
              <input type="radio" className="hidden" checked={isSelected} onChange={() => handleSingleChoice(opt.id)} />
              <span className="font-bold">{opt.text}</span>
            </label>
          );
        })}

        {question.type === QuestionType.MULTIPLE_CHOICE && question.options?.map((opt, i) => {
          const isSelected = Array.isArray(answer) && answer.includes(opt.id);
          return (
            <label 
              key={opt.id} 
              className={`flex items-center p-4 rounded-2xl border-2 transition-all cursor-pointer ${
                isStylized 
                  ? (isSelected ? 'border-slate-900 bg-emerald-400 text-slate-900 neo-shadow translate-x-1' : 'border-slate-100 hover:border-slate-300 text-slate-700')
                  : (isSelected ? 'border-indigo-600 bg-indigo-50 text-indigo-700 shadow-sm' : 'border-slate-100 hover:bg-slate-50 text-slate-600')
              } ${isGraded ? 'pointer-events-none opacity-80' : ''}`}
            >
              <div className={`w-8 h-8 rounded-lg border flex items-center justify-center mr-4 text-xs font-black transition-all ${
                isStylized 
                  ? (isSelected ? 'bg-white text-emerald-600 border-slate-900' : 'bg-slate-50 text-slate-400 border-slate-200')
                  : (isSelected ? 'bg-indigo-600 text-white border-transparent' : 'bg-white text-slate-300 border-slate-200')
              }`}>
                 {String.fromCharCode(65 + i)}
              </div>
              <input type="checkbox" className="hidden" checked={isSelected} onChange={() => handleMultipleChoice(opt.id)} />
              <span className="font-bold">{opt.text}</span>
            </label>
          );
        })}

        {question.type === QuestionType.TRUE_FALSE && (
          <div className="flex gap-6">
            {['true', 'false'].map(val => {
              const isSelected = answer === val;
              return (
                <button
                  key={val}
                  onClick={() => handleTrueFalse(val)}
                  className={`flex-1 py-5 rounded-2xl border-2 font-black capitalize transition-all ${
                    isStylized 
                      ? (isSelected ? 'border-slate-900 bg-emerald-400 text-slate-900 neo-shadow' : 'border-slate-100 text-slate-400 hover:border-slate-300')
                      : (isSelected ? 'border-indigo-600 bg-indigo-600 text-white shadow-lg' : 'border-slate-100 bg-white text-slate-400 hover:bg-slate-50')
                  } ${isGraded ? 'pointer-events-none' : ''}`}
                >
                  {val}
                </button>
              );
            })}
          </div>
        )}

        {question.type === QuestionType.FILL_IN_THE_BLANK && (
          <div className="space-y-4">
            {question.correctAnswers.map((_, bIdx) => {
              const currentVal = Array.isArray(answer) ? (answer[bIdx] || '') : (bIdx === 0 ? (answer as string) : '');
              return (
                <div key={bIdx} className="flex items-center gap-4">
                  <div className={`w-8 h-8 flex-shrink-0 text-[10px] font-black rounded-lg flex items-center justify-center ${
                    isStylized ? 'bg-slate-900 text-white' : 'bg-indigo-100 text-indigo-600'
                  }`}>
                    {bIdx + 1}
                  </div>
                  <input
                    type="text"
                    placeholder={`Answer for entry ${bIdx + 1}...`}
                    value={currentVal}
                    onChange={(e) => handleBlankChange(bIdx, e.target.value)}
                    className={`flex-grow p-4 rounded-2xl border-2 transition-all font-bold placeholder:font-normal placeholder:opacity-30 outline-none ${
                      isStylized ? 'border-slate-900 focus:bg-violet-50' : 'border-slate-200 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100'
                    }`}
                    disabled={isGraded}
                  />
                </div>
              );
            })}
          </div>
        )}

        {question.type === QuestionType.SUBJECTIVE && (
          <textarea
            placeholder="Document your full reasoning here..."
            rows={6}
            value={answer as string || ''}
            onChange={(e) => !isGraded && onChange(e.target.value)}
            className={`w-full p-6 transition-all font-bold placeholder:font-normal outline-none ${
              isStylized 
                ? 'rounded-[30px] border-2 border-slate-900 focus:bg-violet-50' 
                : 'rounded-2xl border-2 border-slate-200 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100'
            }`}
            disabled={isGraded}
          />
        )}
      </div>
    </div>
  );
};
